const articlesDB = [
    // ============================================================
    // УСТАВ МО (ЕДИНЫЙ УСТАВ МИНИСТЕРСТВА ОБОРОНЫ)
    // ============================================================
    { id: 1, law: "Устав МО", chapter: "I. Общие положения", point: "1.1", text: "Данный документ является основным документом Федеральной Тюрьмы, обязательным для прочтения.", category: "Устав МО" },
    { id: 2, law: "Устав МО", chapter: "I. Общие положения", point: "1.2", text: "Каждый сотрудник обязан знать, соблюдать и выполнять все пункты описанные в данном документе.", category: "Устав МО" },
    { id: 3, law: "Устав МО", chapter: "I. Общие положения", point: "1.3", text: "Настоящий Устав определяет права и обязанности сотрудников и взаимоотношения между ними, обязанности основных должностных лиц и взводов.", category: "Устав МО" },
    { id: 4, law: "Устав МО", chapter: "I. Общие положения", point: "1.4", text: "Данный уставной документ предписывает для каждого сотрудника наказание за нарушение документа.", category: "Устав МО" },
    { id: 5, law: "Устав МО", chapter: "I. Общие положения", point: "1.5", text: "Незнание данного документа не освобождает никого от ответственности и от наказания.", category: "Устав МО" },
    { id: 6, law: "Устав МО", chapter: "I. Общие положения", point: "1.6", text: "Данный уставной документ может потерпеть изменения в любой момент. (С одобрения следящей администрации).", category: "Устав МО" },
    { id: 7, law: "Устав МО", chapter: "I. Общие положения", point: "1.7", text: "Звания присутствующие в Тюрьме указаны ниже:<ul><li>Охранник [1]</li><li>Конвоир [2]</li><li>Дежурный [3]</li><li>Ст. дежурный [4]</li><li>Надзиратель [5]</li><li>Начальник блока [6]</li><li>Инспектор [7]</li><li>Начальник инспекции [8]</li><li>Зам. Начальника Тюрьмы [9]</li><li>Начальник Тюрьмы [10]</li></ul>", category: "Устав МО" },
    { id: 8, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.1", text: "Сотрудник тюрьмы имеет право открыть огонь по гражданскому лицу в следующих случаях:<ul><li>в случае нападения этого лица на сотрудника или других сотрудников тюрьмы, а также работников других государственных структур;</li><li>в случае если у гражданского лица в руках огнестрельное оружие в пределах любого из военных объектов или охраняемой территории вокруг них;</li><li>в случае отказа этого гражданского лица подчиниться приказу покинуть охраняемую территорию;</li><li>в случае получения соответствующего приказа от офицеров или Начальства.</li></ul>", category: "Устав МО" },
    { id: 9, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.2", text: "Сотрудник тюрьмы имеет право открыть огонь по гражданскому лицу из травматического оружия(весь арсенал который доступен в оружейной), если гражданское лицо отказывается сотрудничать и подчиняться приказам во время проведения призыва новобранцев в Тюрьму на территории любого из военкоматов, а также на прилегающей к военкоматам территорий.(Только в случае, если было нападение с оружием на сотрудника).", category: "Устав МО" },
    { id: 10, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.3", text: "Сотрудник тюрьмы имеет право на отдых в неслужебное время согласно пункту 16 действующего устава, за исключением чрезвычайных ситуаций, или приказа Начальства которые имеют право отменить неслужебное время по своему усмотрению для любого сотрудника тюрьмы.", category: "Устав МО" },
    { id: 11, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.4", text: "Сотрудник тюрьмы имеет право покинуть территорию своего охраняемого объекта в неслужебное время, предварительно сняв форму и сдав табельное оружие на склад.", category: "Устав МО" },
    { id: 12, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.5", text: "Сотрудник тюрьмы имеет право оставлять свое личное транспортное средство в пределах своего охраняемого объекта в местах специально выделенных для этого внутренним распорядком Тюрьмы Строгого Режима.", category: "Устав МО" },
    { id: 13, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.6", text: "Начальство тюрьмы и старший офицерский состав имеют право ставить личные транспортные средства где угодно в пределах своего охраняемого объекта, если это не мешает движению других транспортных средств и работе Тюрьмы в целом.", category: "Устав МО" },
    { id: 14, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.7", text: "Сотрудник тюрьмы имеет право на повышение по службе в специально отведенное для этого время, которое устанавливается внутренним распорядком Тюрьмы.", category: "Устав МО" },
    { id: 15, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.8", text: "Сотрудник тюрьмы имеет право на повышение в звание согласно рапортам о проделанной работе, который ему необходимо разместить в соответствующем разделе на официальном портале Министерства Обороны в том случае, если имеется свободное место на это звание.", category: "Устав МО" },
    { id: 16, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.9", text: "Сотрудник тюрьмы имеет право подать жалобу на имя Начальника , если он считает что другие сотрудники или офицеры Тюрьмы нарушают настоящий Устав. Жалобу можно подать в соответствующем разделе на официальном портале Министерства Обороны.", category: "Устав МО" },
    { id: 17, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.10", text: "Сотрудники стажерского и дежурного состава имеют право покидать территорию своего охраняемого объекта в служебное время только с разрешения старших офицеров, и под присмотром любого офицера, если это не прописано в правилах отвечающих за внутренний распорядок Тюрьмы.", category: "Устав МО" },
    { id: 18, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.11", text: "Сотрудник младшего офицерского состава имеет право отпроситься у Начальства или старших офицеров, с территории своего охраняемого объекта по личным делам на короткое время.", category: "Устав МО" },
    { id: 19, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.12", text: "Все офицеры тюрьмы имеют право передвигаться по территории своей базы на тюремном транспорте, доступном их званию.", category: "Устав МО" },
    { id: 20, law: "Устав МО", chapter: "II. Основные обязанности сотрудников", point: "2.13", text: "Начальство Тюрьмы и Старшие Офицеры Тюрьмы имеют право в служебных целях покинуть свой охраняемый объект в любое время, а также использовать служебную технику на своё усмотрение.", category: "Устав МО" },

    { id: 21, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.1", text: "Сотрудник обязан соблюдать каждый пункт данного уставного документа, в независимости от занимаемой должности.", category: "Устав МО" },
    { id: 22, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.2", text: "Сотрудник обязан знать свои права, предписанные соответствующими документами.", category: "Устав МО" },
    { id: 23, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.3", text: "Сотрудник обязан соблюдать все действующие пункты устава.", category: "Устав МО" },
    { id: 24, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.4", text: "Сотрудник обязан с честью и доблестью нести свою службу.", category: "Устав МО" },
    { id: 25, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.5", text: "Сотрудник обязан уважать других сотрудников в независимости от их звания.", category: "Устав МО" },
    { id: 26, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.6", text: "Сотрудник обязан исполнять приказы руководящего состава Тюрьмы, а также Начальника Тюрьмы.", category: "Устав МО" },
    { id: 27, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.7", text: "Сотрудник обязан соблюдать субординацию по отношению к другим сотрудникам.", category: "Устав МО" },
    { id: 28, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.8", text: "Сотрудник обязан сообщать в рацию о заступлении на пост, выездах на поставки боеприпасов, о нападении на ВЧ.", category: "Устав МО" },
    { id: 29, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.9", text: "Сотрудник обязан соблюдать пропускной режим министерства обороны.", category: "Устав МО" },
    { id: 30, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.10", text: "Сотрудник обязан соблюдать правила автопарка министерства обороны.", category: "Устав МО" },
    { id: 31, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.11", text: "Сотрудник обязан соблюдать правила проведения призыва в министерстве обороны.", category: "Устав МО" },
    { id: 32, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.12", text: "Сотрудник обязан соблюдать правила поведения в строю.", category: "Устав МО" },
    { id: 33, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.13", text: "Сотрудник обязан носить при себе включенную рацию и соблюдать правила ее использования.", category: "Устав МО" },
    { id: 34, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.14", text: "Сотрудник обязан соблюдать правила поведения на посту.", category: "Устав МО" },
    { id: 35, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.15", text: "Сотрудник обязан охранять территорию тюрьмы и не пропускать на нее представителей преступных группировок, а также гражданских лиц.", category: "Устав МО" },
    { id: 36, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.16", text: "Сотрудник обязан исполнять приказы старшего по званию и руководства взвода, если эти приказы не перечат Уставу.", category: "Устав МО" },
    { id: 37, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.17", text: "Сотрудник обязан подчиняться строго руководящему составу тюрьмы, руководству своего взвода.", category: "Устав МО" },
    { id: 38, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.18", text: "Сотрудник обязан находится в служебной форме на территории Тюрьмы не в отпускное время.", category: "Устав МО" },
    { id: 39, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.19", text: "Сотрудник, охраняющий территорию Федеральной Тюрьмы обязан давать возможность заключенным работать на исправительных работах [Готовить еду | Стирать одежду | Носить ящики | Собирать мусор].", category: "Устав МО" },
    { id: 40, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.20", text: "Сотрудник, охраняющий территорию Федеральной Тюрьмы обязан давать возможность заключенным на выполнение своих нужд.", category: "Устав МО" },
    { id: 41, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.21", text: "Сотрудник имеет право повысить срок заключенному согласно системе повышения срока.", category: "Устав МО" },
    { id: 42, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.22", text: "Сотрудник имеет право перевести заключенного в камеру в случае Чрезвычайной Ситуации или поднятия Бунта.", category: "Устав МО" },
    { id: 43, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.23", text: "Сотрудник Федеральной Тюрьмы обязан следить за порядком на территории тюрьмы.", category: "Устав МО" },
    { id: 44, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.24", text: "Сотрудник имеет полное право на обыск заключенного.", category: "Устав МО" },
    { id: 45, law: "Устав МО", chapter: "III. Обязанности Сотрудников Тюрьмы", point: "3.25", text: "Сотрудник обязан общаться с заключенными соблюдая субординацию в любой ситуации.", category: "Устав МО" },

    { id: 46, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.1", text: "Запрещено сотруднику нарушать данный уставной документ.", category: "Устав МО" },
    { id: 47, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.2", text: "Запрещено сотруднику нарушать ЕФК. ФП а также УК.", category: "Устав МО" },
    { id: 48, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.3", text: "Запрещено сотруднику заниматься криминальной деятельностью, а также сотрудничать с нарушителями закона которые являются членами преступных группировок.", category: "Устав МО" },
    { id: 49, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.4", text: "Запрещено сотруднику самовольно покидать базу без ведома старшего состава тюрьмы, либо Начальства.", category: "Устав МО" },
    { id: 50, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.5", text: "Запрещено сотруднику игнорировать приказы руководящего состава тюрьмы.", category: "Устав МО" },
    { id: 51, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.6", text: "Запрещено сотруднику унижать честь и достоинство любого гражданина штата.", category: "Устав МО" },
    { id: 52, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.7", text: "Запрещено сотруднику злоупотреблять служебными полномочиями.", category: "Устав МО" },
    { id: 53, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.8", text: "Запрещено сотруднику выпрашивать повышение, премию, либо намекать на те или иные действия.", category: "Устав МО" },
    { id: 54, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.9", text: "Запрещено сотруднику производить выстрелы из огнестрельного оружия без весомой причины.", category: "Устав МО" },
    { id: 55, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.10", text: "Запрещено сотруднику не появляться на рабочем месте более десяти дней, при этом не находясь в отпуске.", category: "Устав МО" },
    { id: 56, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.11", text: "Запрещено сотруднику обманывать, либо вводить в заблуждение весь состав Министерства Обороны.", category: "Устав МО" },
    { id: 57, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.12", text: "Запрещено сотруднику находится на территории тюрьмы без бронежилета на теле не в отпускное время, исключением является старший офицерский состав.", category: "Устав МО" },
    { id: 58, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.13", text: "Запрещено сотруднику в одиночку перевозить боеприпасы в отделения полицейских департаментов. Исключение: Ночное время с 23:00 до 9:00 и при условии что склад Департамента МЮ не полный.", category: "Устав МО" },
    { id: 59, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.14", text: "Запрещено сотруднику спать в интерьере в рабочее и не рабочее время. (Разрешено стоять в АФК в: a) Личный дом/квартира; b) Семейная квартира; c) Арендованные комнаты; d) Отели; e) Трейлеры; f) Личные транспортные средства с интерьером (Enforcer, Boxville и т.п.); g) Стрип-клуб; h) Подземные паркинги. i) Больницы штата.", category: "Устав МО" },
    { id: 60, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.15", text: "Запрещено сотруднику вести общение по волне департамента до звания Начальник Блока[6].", category: "Устав МО" },
    { id: 61, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.16", text: "Запрещено сотруднику самовольно переходить в другие взводы.", category: "Устав МО" },
    { id: 62, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.17", text: "Запрещено использовать личное ТС на службе. (Исключение: 8-10 ранги).", category: "Устав МО" },
    { id: 63, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.18", text: "Запрещено сотруднику носить предметы, скрывающие лицо(маски). Исключение: во время ЧС на Территории Тюрьмы.", category: "Устав МО" },
    { id: 64, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.19", text: "Сотрудник не имеет право оскорблять заключенных, провоцировать на конфликт, неадекватно ввести себя, применять физическую силу без весомых причин.", category: "Устав МО" },
    { id: 65, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.20", text: "Сотруднику запрещено помогать заключенным в совершении подозрительных действий.", category: "Устав МО" },
    { id: 66, law: "Устав МО", chapter: "IV. Запреты для Сотрудников Тюрьмы", point: "4.21", text: "Сотруднику запрещено нарушать Устав ФТ, Систему повышения срока.", category: "Устав МО" },

    { id: 67, law: "Устав МО", chapter: "V. Табель о званиях сотрудников Тюрьмы", point: "5.1", text: "Стажерским составом считаются сотрудники тюрьмы со звания Охранник [1] до звания Конвоир [2] включительно.", category: "Устав МО" },
    { id: 68, law: "Устав МО", chapter: "V. Табель о званиях сотрудников Тюрьмы", point: "5.2", text: "Дежурным составом считаются сотрудники тюрьмы со звания Дежурный[3] до звания Ст. Дежурный[4] включительно.", category: "Устав МО" },
    { id: 69, law: "Устав МО", chapter: "V. Табель о званиях сотрудников Тюрьмы", point: "5.3", text: "Младшим офицерским составом считаются сотрудники тюрьмы со звания Надзиратель[5] до звания Начальник блока[6] включительно.", category: "Устав МО" },
    { id: 70, law: "Устав МО", chapter: "V. Табель о званиях сотрудников Тюрьмы", point: "5.4", text: "Старшим офицерским составом считаются сотрудники тюрьмы со звания Инспектор[7] до звания Начальник инспекции[8] включительно.", category: "Устав МО" },
    { id: 71, law: "Устав МО", chapter: "V. Табель о званиях сотрудников Тюрьмы", point: "5.5", text: "Начальник/Зам. Начальника тюрьмы являются высшими офицерами и непосредственно отвечают за работу Тюрьмы, обучение, воспитание и повседневную деятельность состава.", category: "Устав МО" },

    { id: 72, law: "Устав МО", chapter: "VI. Охрана территории Тюрьмы", point: "6.1", text: "В любое время суток на территорию Тюрьмы Строгого Режима, не допускаются гражданские лица, или лица из других государственных структур, без особого разрешения.", category: "Устав МО" },
    { id: 73, law: "Устав МО", chapter: "VI. Охрана территории Тюрьмы", point: "6.2", text: "Вход в воздушное пространство над территорией любого из охраняемых объектов без разрешения возможен только для представителей министерства юстиции и только в случаях чрезвычайной ситуации, в остальных случаях нарушения воздушного пространства сотрудники имеют право открыть огонь на поражение без предупреждения.", category: "Устав МО" },
    { id: 74, law: "Устав МО", chapter: "VI. Охрана территории Тюрьмы", point: "6.3", text: "Особое разрешение на посещение территории, а также разрешение на вход в воздушное пространство охраняемого объекта, могут быть выданы только Начальством тюрьмы и старшим офицерским составом на данном охраняемом объекте, или старшим по званию командующим офицером охраняемого объекта, находящимся в Штате в этот момент.", category: "Устав МО" },
    { id: 75, law: "Устав МО", chapter: "VI. Охрана территории Тюрьмы", point: "6.4", text: "Губернатор штата, директор РО ФБР и их заместители могут находиться на охраняемых объектах по предъявлению документов: 1) Иные лица не имеют право находиться на охраняемых объектах, исключением является разрешение со стороны командования Тюрьмы; 2) Иные сотрудники РО ФБР могут находиться на территории охраняемых объектов только в тех случаях, если агенты ведут оперативно-следственную деятельность, при предъявлении документов с сопровождением старшего офицера. Все выше перечислены должностные лица должны соблюдать и выполнять требования указанные в пункте 6.2. данного уставного акта для пересечения воздушного пространства любого охраняемого объекта находящегося в штате.", category: "Устав МО" },

    { id: 76, law: "Устав МО", chapter: "VII. Правила постов", point: "7.1", text: "Сотрудник при заступление на пост обязан иметь хорошее самочувствие и не иметь чувства голода.", category: "Устав МО" },
    { id: 77, law: "Устав МО", chapter: "VII. Правила постов", point: "7.2", text: "Сотрудник при заступление на пост обязан иметь при себе необходимое вооружение [Бронежилет, M4, Desert Eagle] и необходимое количество боеприпасов.", category: "Устав МО" },
    { id: 78, law: "Устав МО", chapter: "VII. Правила постов", point: "7.3", text: "Сотрудник при заступление на пост обязан сообщить в рацию.", category: "Устав МО" },
    { id: 79, law: "Устав МО", chapter: "VII. Правила постов", point: "7.4", text: "Сотруднику запрещено спать или дремать на посту.", category: "Устав МО" },
    { id: 80, law: "Устав МО", chapter: "VII. Правила постов", point: "7.5", text: "Сотрудник обязан осуществлять доклад с поста каждые 10 минут.", category: "Устав МО" },
    { id: 81, law: "Устав МО", chapter: "VII. Правила постов", point: "7.6", text: "Сотрудник обязан сообщить о покидание поста.", category: "Устав МО" },
    { id: 82, law: "Устав МО", chapter: "VII. Правила постов", point: "7.7", text: "Форма доклада: Заступление на пост /r Докладывает Звание Фамилия, заступил на пост: (Указать пост). Доклад с поста /r Доклад: Докладывает Звание Фамилия, нахожусь на посту: (Указать пост), состояние: (ЧС/Спокойно/Нападение). Покидание поста /r Докладывает Звание Фамилия, покидаю пост: (Указать пост) последнее состояние: (ЧС/Спокойно/Нападение).", category: "Устав МО" },
    { id: 83, law: "Устав МО", chapter: "VII. Правила постов", point: "7.8", text: "Чтобы заступить на пост, нужно занять его. (N на посту).", category: "Устав МО" },

    { id: 84, law: "Устав МО", chapter: "VIII. Пропускной режим", point: "8.1", text: "Пропуск на территорию осуществляется с согласия всех сторон, а именно лиц желающих посетить территорию тюрьмы по особо важному вопросу и одобрению на посещение со стороны лиц офицерского состава Тюрьмы с учетом раннего предупреждения о прибытии.", category: "Устав МО" },
    { id: 85, law: "Устав МО", chapter: "VIII. Пропускной режим", point: "8.2", text: "Нарушение воздушного/сухопутного/водного пространства охраняемой территории, разрешено только с разрешения офицерского состава, а именно того лица, который в данный момент суток является старшим по званию, находящимся на территории.", category: "Устав МО" },
    { id: 86, law: "Устав МО", chapter: "VIII. Пропускной режим", point: "8.3", text: "Нарушение любого территориального пространства охраняемой территории без разрешения старших по званию подлежат немедленной ликвидации. Исключение см. в пункте 6.4 данного уставного акта.", category: "Устав МО" },
    { id: 87, law: "Устав МО", chapter: "VIII. Пропускной режим", point: "8.4", text: "При проникновение через КПП в светлое время суток нарушителя следует предупредить о проникновении на охраняемую территорию, попросить покинуть объект и в случае неповиновения применить силы для ликвидации нарушителя.", category: "Устав МО" },

    { id: 88, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.1", text: "Служебная форма одежды является неотъемлемым атрибутом службы, определяющим принадлежность сотрудников к Министерству Обороны.", category: "Устав МО" },
    { id: 89, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.2", text: "Форма сотрудника всегда должна быть целого состояние и приемлемого вида", category: "Устав МО" },
    { id: 90, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.3", text: "Служебная форма одежды подразделяется по категориям, в зависимости от звания.", category: "Устав МО" },
    { id: 91, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.4", text: "Сотрудник обязан носить форму согласно своему званию.", category: "Устав МО" },
    { id: 92, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.5", text: "Сотруднику запрещено носить кейс с деньгами. (Исключение 9-10 ранг).", category: "Устав МО" },
    { id: 93, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.6", text: "Сотруднику разрешено носить: армейский берет, армейскую каску, респиратор, часы, тактические наушники, бронежилет, прозрачные и солнцезащитные очки в черной оправе, монокль, повязку на глаз, платок на шею, прибор ночного видения (после 21:00 и до 7:00), попугай, машинка на п/у, сердце на грудь, доллар на грудь, ключ на грудь, замок на грудь, череп на грудь, неяркую шапку, щит на спину любого цвета, гитару, крестик на грудь, фотоаппарат на грудь, патрон на грудь, звезду шерифа на грудь, усы, борода, золотые погоны, полицейская фуражка, Desert Eagle, АК-47, M4, тактический шлем, золотой Desert Eagle, обрезы, пояс с боеприпасами, полицейский пояс, граната «Advance», длинный Desert Eagle, Военный рюкзак, Связка гранат, Траншейная лопата. Новый сет военного", category: "Устав МО" },
    { id: 94, law: "Устав МО", chapter: "IX. Форма одежды", point: "9.7", text: "Все остальные аксессуары, не указанные в пункте 9.6, запрещено носить в рабочее время и в форме, за их ношение вы будете привлечены к ответственности руководством Тюрьмы. (Подробнее о форме одежде можно узнать в разделе F.A.Q. по Министерству Обороны).", category: "Устав МО" },

    { id: 95, law: "Устав МО", chapter: "X. Субординация", point: "10.1", text: "Сотрудники должны постоянно служить примером высокой культуры, скромности и выдержанности.", category: "Устав МО" },
    { id: 96, law: "Устав МО", chapter: "X. Субординация", point: "10.2", text: "Взаимоотношения между сотрудниками строятся на основе взаимного уважения.", category: "Устав МО" },
    { id: 97, law: "Устав МО", chapter: "X. Субординация", point: "10.3", text: "По вопросам службы сотрудники должны обращаться друг к другу на \"Вы\" и последующей форме: Звание Фамилия Пример: \"Начальник Тёрнер, разрешите обратиться?\"", category: "Устав МО" },
    { id: 98, law: "Устав МО", chapter: "X. Субординация", point: "10.4", text: "Искажение тюремных званий, употребление нецензурных слов, кличек и прозвищ, грубость несовместимы с понятием достоинства сотрудника.", category: "Устав МО" },
    { id: 99, law: "Устав МО", chapter: "X. Субординация", point: "10.5", text: "Вне строя, отдавая или получая приказ, сотрудники обязаны принять строевую стойку.", category: "Устав МО" },
    { id: 100, law: "Устав МО", chapter: "X. Субординация", point: "10.6", text: "При обращении к другому сотруднику в присутствии командира [старшего по званию] у него необходимо спросить на это разрешение.", category: "Устав МО" },
    { id: 101, law: "Устав МО", chapter: "X. Субординация", point: "10.7", text: "Если при встрече нельзя свободно разойтись с старшим по званию, сотрудник обязан уступить дорогу и, приветствуя, пропустить его; при необходимости обогнать старшего по званию, сотрудник должен спросить на то разрешение.", category: "Устав МО" },
    { id: 102, law: "Устав МО", chapter: "X. Субординация", point: "10.8", text: "Сотрудники должны быть вежливыми по отношению к гражданскому населению, проявлять особое внимание к инвалидам, пожилым людям, женщинам и детям.", category: "Устав МО" },
    { id: 103, law: "Устав МО", chapter: "X. Субординация", point: "10.9", text: "Сотрудникам запрещается держать руки в карманах одежды, сидеть или курить в присутствии старшего по званию без его разрешения.", category: "Устав МО" },
    { id: 104, law: "Устав МО", chapter: "X. Субординация", point: "10.10", text: "Трезвый образ жизни должен быть повседневной нормой поведения всех сотрудников.", category: "Устав МО" },
    { id: 105, law: "Устав МО", chapter: "X. Субординация", point: "10.11", text: "Правила служебной вежливости, поведения и выполнения приветствия обязательны также для граждан, уволенных со службы, при ношении ими служебной формы одежды.", category: "Устав МО" },

    { id: 106, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.1", text: "Служебная Рация предусмотрена для связи между сотрудниками.", category: "Устав МО" },
    { id: 107, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.2", text: "Рацией разрешено пользоваться строго в служебных целях.", category: "Устав МО" },
    { id: 108, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.3", text: "Запрещено использовать рацию для покупки, продажи и рекламы имущества.", category: "Устав МО" },
    { id: 109, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.4", text: "Запрещено использовать при разговорах по рации брань, ругань и оскорбления сотрудников.", category: "Устав МО" },
    { id: 110, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.5", text: "Запрещено сотруднику создавать помехи в общении по рации.", category: "Устав МО" },
    { id: 111, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.6", text: "Сотрудник обязан вести общение по рации с указанием своего отряда.", category: "Устав МО" },
    { id: 112, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.7", text: "Сотрудник обязан вести общение по рации с другими сотрудниками исключительно в уважительной форме.", category: "Устав МО" },
    { id: 113, law: "Устав МО", chapter: "XI. Использование служебной Рации", point: "11.8", text: "При общение в рации не используются не системные тэги. [Только те, что устанавливают лидер/заместители через /settag]", category: "Устав МО" },

    { id: 114, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.1.1", text: "Командир обязан указать место, время, порядок построения, форму одежды и снаряжение, а также какое иметь вооружение и служебную технику; при необходимости назначить наблюдателя;", category: "Устав МО" },
    { id: 115, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.1.2", text: "Командир обязан проверить и знать наличие в строю подчиненных своего взвода, а также вооружения, служебной техники, боеприпасов, средств индивидуальной защиты;", category: "Устав МО" },
    { id: 116, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.1.3", text: "Командир обязан проверить внешний вид подчиненных, а также наличие снаряжения и правильность его подготовки;", category: "Устав МО" },
    { id: 117, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.1.4", text: "Командир обязан поддерживать дисциплину строя и требовать точного выполнения подразделениями команд и сигналов, а сотрудниками своих обязанностей в строю;", category: "Устав МО" },
    { id: 118, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.1.5", text: "Командир обязан при построении подразделений с вооружением и служебной техникой произвести внешний осмотр их, а также проверить наличие и исправность оборудования для перевозки личного состава.", category: "Устав МО" },
    { id: 119, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.1", text: "Сотрудник обязан вовремя явиться в строй.", category: "Устав МО" },
    { id: 120, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.2", text: "Сотрудник обязан проверить исправность своего оружия, закрепленных за ним вооружения и служебной техники, боеприпасов, средств индивидуальной защиты, обмундирования и снаряжения;", category: "Устав МО" },
    { id: 121, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.3", text: "Сотрудник обязан аккуратно заправить обмундирование, правильно надеть и подогнать снаряжение, помочь товарищу устранить замеченные недостатки;", category: "Устав МО" },
    { id: 122, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.4", text: "Сотрудник обязан знать свое место в строю, уметь быстро, без суеты занять его; в движении сохранять равнение, установленные интервал и дистанцию; соблюдать требования безопасности; не выходить из строя [машины] без разрешения;", category: "Устав МО" },
    { id: 123, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.5", text: "В строю без разрешения не разговаривать и не курить, не использовать сотовые телефоны; быть внимательным к приказаниям и командам своего командира, быстро и точно их выполнять, не мешая другим;", category: "Устав МО" },
    { id: 124, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.6", text: "В строю не держать в руках оружия, если на то не было команды;", category: "Устав МО" },
    { id: 125, law: "Устав МО", chapter: "XII. Обязанности командиров и сотрудников перед построением и в строю", point: "12.2.7", text: "Передавать приказания, команды без искажений, громко и четко.", category: "Устав МО" },

    { id: 126, law: "Устав МО", chapter: "XIII. Использование служебного транспорта", point: "13.1", text: "Сотрудникам допускается использование служебного транспорта только в целях исполнения обязанностей.", category: "Устав МО" },
    { id: 127, law: "Устав МО", chapter: "XIII. Использование служебного транспорта", point: "13.2", text: "Стажерскому составу допускается использование служебного транспорта, таких как Фуры", category: "Устав МО" },
    { id: 128, law: "Устав МО", chapter: "XIII. Использование служебного транспорта", point: "13.3", text: "Дежурному составу с разрешения офицерского состава допускается использование: Фур, Автобусов, Хаммеров, Каргобобов.", category: "Устав МО" },
    { id: 129, law: "Устав МО", chapter: "XIII. Использование служебного транспорта", point: "13.4", text: "Младшему офицерскому составу допускается использование: Фур, Автобусов, Хаммеров, Каргобобов.", category: "Устав МО" },
    { id: 130, law: "Устав МО", chapter: "XIII. Использование служебного транспорта", point: "13.5", text: "Старшему офицерскому составу допускается использование всего имеющегося транспорта.", category: "Устав МО" },

    { id: 131, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.1", text: "На призыве должен присутствовать офицер управляющий призывом - Зам. Начальника/Начальник тюрьмы.", category: "Устав МО" },
    { id: 132, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.2", text: "Управляющий обязан сообщить о предстоящем призыве офицерам за 15 минут до начала, а также решить, кто будет задействован.", category: "Устав МО" },
    { id: 133, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.3", text: "Сотрудники, задействованные в проведение призыва, должны находиться на КПП за 5 минут до начала призыва.", category: "Устав МО" },
    { id: 134, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.4", text: "Оканчивать призыв разрешается только через час после его начала.", category: "Устав МО" },
    { id: 135, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.5", text: "После окончания призыва для новобранцев должна быть проведена экскурсия по территории и лекция.", category: "Устав МО" },
    { id: 136, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.6", text: "Сон во время призыва строго запрещен. (Афк не более 1 минуты).", category: "Устав МО" },
    { id: 137, law: "Устав МО", chapter: "XIV. Проведение призыва", point: "14.7", text: "В случаях, когда управляющему призывом (Зам. Начальника/Начальнику) необходимо отлучиться или когда управляющий за несколько минут до призыва по весомым причинам не может явиться на призыв, управляющий в праве назначить любого сотрудника из старшего офицерского состава для помощи на призыве. Управляющему необходимо вернуться в течение 5 минут.", category: "Устав МО" },

    { id: 138, law: "Устав МО", chapter: "XV. Испытательные сроки", point: "15.1", text: "С 5 на 6 ранг - 2 дня на должности", category: "Устав МО" },
    { id: 139, law: "Устав МО", chapter: "XV. Испытательные сроки", point: "15.2", text: "С 6 на 7 ранг - 4 дня на должности", category: "Устав МО" },
    { id: 140, law: "Устав МО", chapter: "XV. Испытательные сроки", point: "15.3", text: "С 7 на 8 ранг - 5 дней на должности", category: "Устав МО" },
    { id: 141, law: "Устав МО", chapter: "XV. Испытательные сроки", point: "15.4", text: "С 8 на 9 ранг - 7 дней на должности", category: "Устав МО" },
    { id: 142, law: "Устав МО", chapter: "XV. Испытательные сроки", point: "15.5", text: "9 ранг для увольнения без варна - 15 дней на должности", category: "Устав МО" },

    { id: 143, law: "Устав МО", chapter: "XVI. График рабочего дня", point: "16.1", text: "Сотрудники несут службу каждый день недели (понедельник - воскресенье). Рабочий день начинается в 10:00 и заканчивается в 21:30.", category: "Устав МО" },
    { id: 144, law: "Устав МО", chapter: "XVI. График рабочего дня", point: "16.2", text: "Сотрудник обязан сдать форму, перед уходом в увольнительное время.", category: "Устав МО" },
    { id: 145, law: "Устав МО", chapter: "XVI. График рабочего дня", point: "16.3", text: "У каждого сотрудника начиная с ранга [1] имеется обеденный перерыв с 14:00 до 16:00, это время приравнивается к увольнительному.", category: "Устав МО" },

    { id: 146, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.1", text: "Взятие отпуска разрешается только с звания Надзиратель[5].", category: "Устав МО" },
    { id: 147, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.2", text: "Минимально допустимый отпуск - 1 день.", category: "Устав МО" },
    { id: 148, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.3.1", text: "Со звания Надзиратель[5] до звания Зам. Начальника[9] - 7 дней.", category: "Устав МО" },
    { id: 149, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.3.2", text: "С звания Начальник[10] - 3 дня.", category: "Устав МО" },
    { id: 150, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.4", text: "Перед уходом в отпуск сотрудник обязан отработать на должности не менее, чем его испытательный срок на звании.", category: "Устав МО" },
    { id: 151, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.5", text: "Перед уходом в отпуск любой сотрудник обязан заполнить заявление на отпуск в специальной теме.", category: "Устав МО" },
    { id: 152, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.6", text: "Отправлять в отпуск [увольнять] может только руководящий состав.", category: "Устав МО" },
    { id: 153, law: "Устав МО", chapter: "XVII. Отпуск Сотрудников", point: "17.7", text: "Если сотрудник имеет выговоры, то в отпуск он уйти не может.", category: "Устав МО" },

    { id: 154, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.1", text: "Министерство обороны и министерство юстиции обязуются между собой проводить совместные учения, участвовать в совместной обороне штата и его граждан в случае необходимости.", category: "Устав МО" },
    { id: 155, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.2", text: "Министерство обороны обязуется ежедневно поставлять боеприпасы в департаменты министерства юстиции. Министерство обороны обязуются прекратить поставки боеприпасов в случае, если данное распоряжение поступит от губернатора штата.", category: "Устав МО" },
    { id: 156, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.3", text: "Сотрудникам полицейских департаментов запрещено задерживать сотрудников тюрьмы в форме на территории. Для этого им необходимо связаться с сотрудниками Федерального Бюро Расследований.(Искл. Если он заехал специально на ВЧ)", category: "Устав МО" },
    { id: 157, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.4", text: "Сотрудники тюрьмы обязуются задержать сотрудника департамента министерства юстиции в случае, если тот нарушит правило нахождения на территории Тюрьмы , прописанное в уставе министерства обороны. Применение огнестрельного оружия разрешается лишь в случае, если жизни сотрудника тюрьмы угрожает опасность.", category: "Устав МО" },
    { id: 158, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.5", text: "По окончанию устранения чрезвычайной ситуации, сотрудники департаментов министерства юстиции в праве находится на охраняемом объекте в течении 15 минут. Далее - только с разрешением командования тюрьмы.", category: "Устав МО" },
    { id: 159, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.6", text: "Проведение агитаций между министерствами проводятся по обоюдному согласию двух сторон. Агитационные мероприятия разрешается проводить максимум раз в день.", category: "Устав МО" },
    { id: 160, law: "Устав МО", chapter: "XVIII. Взаимодействие между Министерством Обороны и Министерством Юстиции", point: "19.7", text: "Федеральное Бюро Расследований в праве задерживать сотрудников в форме на территории Тюрьмы, в случае если они находятся в федеральном розыске, для допроса. При этом допрос должен проходить с офицерским составом Тюрьмы(7-10). За несоблюдение 19 раздела устава ТСР, сотрудники Тюрьмы могут получить наказание в виде выговора/увольнения.", category: "Устав МО" },

    { id: 161, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "1.1", text: "Внутренний устав взвода является приложением к Единому уставу министерства обороны, обязательным для соблюдения всеми сотрудниками, состоящем в данном взводе.", category: "Устав МО" },
    { id: 162, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "1.2", text: "Незнание данного документа не освобождает никого от ответственности и от наказания.", category: "Устав МО" },
    { id: 163, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "1.3", text: "Данный уставной документ можете потерпеть изменения в любой момент. [С одобрения следящей администрации].", category: "Устав МО" },
    { id: 164, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "1.4", text: "Код подразделения (Тэг) - [ВОиС]", category: "Устав МО" },
    { id: 165, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.1", text: "Сотрудник взвода имеет право на остановку сотрудника, покидающего военную базу, без разрешения старшего офицерского состава.", category: "Устав МО" },
    { id: 166, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.2", text: "Сотрудник взвода имеет право остановить военнослужащего, использующего служебный транспорт, не соответствующий его званию, либо личное транспортное средство в нарушение установленного порядка. [Исключение: военнослужащие ВП].", category: "Устав МО" },
    { id: 167, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.3", text: "Сотрудник взвода имеет право потребовать у военнослужащего объяснить причину открытия огня, если нарушение или угроза, послужившие основанием для открытия огня, не были очевидны.", category: "Устав МО" },
    { id: 168, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.4", text: "Если на КПП присутствует представители других гос. структур Сотрудник данного взвода имеет право: > Потребовать удостоверение и цель прибытия вне зависимости от его секретности. > Попросить покинуть территорию охраняемой территории, либо же прилегающую территорию, если у предъявившего документа не имеется на то разрешения от старшего офицерского состава.", category: "Устав МО" },
    { id: 169, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.6", text: "Сотрудник взвода имеет право открыть огонь на поражение в случае, если нарушитель оказывает вооружённое сопротивление, представляет непосредственную угрозу жизни или здоровью военнослужащих либо иных лиц, либо отказывается покинуть охраняемую территорию после установленного предупреждения. [Сделав 3 предупредительных выстрела в воздух].", category: "Устав МО" },
    { id: 170, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.7", text: "Сотрудник взвода имеет право отступать от требований ПДД исключительно при выполнении служебной задачи и включённом специальном сигнале, если это необходимо для её выполнения и не создаёт необоснованной угрозы другим участникам движения.", category: "Устав МО" },
    { id: 171, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.8", text: "В случае нападения на служебную фуру сотрудник ВОиС вправе временно не выполнять требования сотрудников МЮ, если их выполнение препятствует отражению нападения или создаёт угрозу жизни и здоровью военнослужащих.", category: "Устав МО" },
    { id: 172, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.9", text: "Сотрудник взвода имеет право при нападении на фуру в городе или в сельской местности начинать оборону с огнестрельного оружия, не оказывая угрозы гражданам штата.", category: "Устав МО" },
    { id: 173, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.10", text: "Сотрудник взвода имеет право идти на таран при нападение и попытке спровоцировать ДТП.", category: "Устав МО" },
    { id: 174, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.11", text: "Сотрудник взвода имеет право запрашивать фуры и боеприпасы у другой армии.", category: "Устав МО" },
    { id: 175, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.12", text: "Сотрудник взвода имеет право выполнять поставки не на ваши объекты поставок при прямом запросе от этих объектов или другой армии.", category: "Устав МО" },
    { id: 176, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.13", text: "Сотрудник взвода имеет право запрашивать сопровождение от МЮ при поставках.", category: "Устав МО" },
    { id: 177, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "2.14", text: "Сотрудник взвода имеет право останавливаться на заправках в случае крайней необходимости.", category: "Устав МО" },
    { id: 178, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.1", text: "Сотруднику взвода запрещено находиться на посту не в полном боекомплекте. [Отсутствие Бронежилета/Оружия].", category: "Устав МО" },
    { id: 179, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.2", text: "Сотруднику взвода запрещено находиться на пост в нездоровом виде. [Менее 50% хп].", category: "Устав МО" },
    { id: 180, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.3", text: "Сотруднику взвода запрещено не осуществлять проверку документов у вновь прибывших лиц, не являющихся сотрудниками вашего охраняемого объекта.", category: "Устав МО" },
    { id: 181, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.4", text: "Сотруднику взвода запрещено открывать огонь в дневное время суток без предупреждения гражданского лица.", category: "Устав МО" },
    { id: 182, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.5", text: "Сотруднику взвода запрещено выпускать с территории военной базы военнослужащих без соответствующего разрешения, за исключением военнослужащих старшего и высшего офицерского состава. [с 7 по 10 порядкового звания]", category: "Устав МО" },
    { id: 183, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.6", text: "Сотруднику взвода запрещено использовать оружие в случаях не предусмотренных уставом.", category: "Устав МО" },
    { id: 184, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.7", text: "Сотруднику взвода запрещено не осуществлять доклад в рацию о заступление на пост/по кидание поста.", category: "Устав МО" },
    { id: 185, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.8", text: "Сотруднику взвода запрещено игнорировать работу в цеху.", category: "Устав МО" },
    { id: 186, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.9", text: "Сотруднику взвода запрещено продавать/хранить боеприпасы.", category: "Устав МО" },
    { id: 187, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.10", text: "Сотруднику взвода запрещено выезжать на поставку без доклада в рацию и одобрения старшего состава ВОиС либо ответственного за поставки военнослужащего. Примеры доклада: /r Доклад: Загружаюсь на складе и выезжаю в полицейский департамент ЛСПД/СФПД/РКШД/ЛВПД/ФБР. /r Доклад: Разгружаюсь на складе ЛСПД/СФПД/РКШД/ЛВПД/ФБР. Возвращаюсь на базу.", category: "Устав МО" },
    { id: 188, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.11", text: "Сотруднику взвода запрещено делать поставки не по маршрутам.", category: "Устав МО" },
    { id: 189, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.12", text: "Сотруднику взвода запрещено покидать служебный транспорт при остановке сотрудниками МЮ без соответствующего требования или необходимости. Исключение: нападение на транспортное средство либо возникновение непосредственной угрозы жизни и здоровью.", category: "Устав МО" },
    { id: 190, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.13", text: "Сотруднику взвода запрещено включать спец. сигналы без весомой на то причины.", category: "Устав МО" },
    { id: 191, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.14", text: "Сотруднику взвода запрещено игнорировать остановку от сотрудников МЮ при езде без спец. сигнала.", category: "Устав МО" },
    { id: 192, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.15", text: "Сотруднику взвода запрещено не блокировать двери при остановке от сотрудников МЮ. [/jlock]", category: "Устав МО" },
    { id: 193, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.16", text: "Сотруднику взвода запрещено при поставках выполнять просьбы от гражданских независимо от ситуации.", category: "Устав МО" },
    { id: 194, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.17", text: "Сотруднику взвода запрещено игнорировать требования постового об остановке при въезде или выезде с военной базы вне зависимости от его звания.", category: "Устав МО" },
    { id: 195, law: "Устав МО", chapter: "Внутренний устав взвода охраны и снабжения [ВОиС]", point: "3.18", text: "Сотруднику взвода запрещено открывать огонь без предупреждения в случае тарана.", category: "Устав МО" },

    { id: 196, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "1.1", text: "Внутренний устав взвода является приложением к Единому уставу министерства обороны, обязательным для соблюдения всеми военнослужащими, состоящем в данном взводе.", category: "Устав МО" },
    { id: 197, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "1.2", text: "Незнание данного документа не освобождает никого от ответственности и от наказания.", category: "Устав МО" },
    { id: 198, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "1.3", text: "Данный уставной документ можете потерпеть изменения в любой момент. [С одобрения следящей администрации].", category: "Устав МО" },
    { id: 199, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "1.4", text: "Код подразделения (Тэг) - [ВОН]", category: "Устав МО" },
    { id: 200, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.1", text: "Военнослужащий взвода имеет право поддерживать субординацию, дисциплину, тем самым показывать пример в расположении и другим военнослужащим.", category: "Устав МО" },
    { id: 201, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.2", text: "Военнослужащий взвода имеет право на обучение будущих офицеров армии, их подготовку как в плане физических, так и интеллектуальных навыков, развивая их во всех военных направлениях.", category: "Устав МО" },
    { id: 202, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.3", text: "Военнослужащий взвода имеет право проводить тренировки для младшего состава армии, чтобы укрепить их теоретические и практические знания полученные входе прохождения службы.", category: "Устав МО" },
    { id: 203, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.4", text: "Военнослужащий взвода имеет право на проведение специальных и общих лекций, экскурсий военнослужащим.", category: "Устав МО" },
    { id: 204, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.5", text: "Военнослужащий взвода имеет право командовать всем младшим составом, для их дальнейшего обучения и выполнения ими прямых приказов и обязанностей.", category: "Устав МО" },
    { id: 205, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.6", text: "Военнослужащий взвода имеет право оказывать помощь другим взводам в вопросах, связанных с его компетенцией и обязанностями, при отсутствии противоречий с распоряжениями руководства армии.", category: "Устав МО" },
    { id: 206, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.7", text: "Военнослужащий взвода имеет право принимать специальные нормативы для повышения навыков военнослужащего и его дальнейшего повышения в звании, такие как: курс офицерской подготовки [КОП].", category: "Устав МО" },
    { id: 207, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.8", text: "Военнослужащий взвода имеет право выдавать наказания, как устные так и письменные с занесением в личное дело военнослужащего [Просить выговор военнослужащему], в случаи невыполнения его приказов и приказов других офицеров, устава министерства обороны.", category: "Устав МО" },
    { id: 208, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "2.9", text: "Военнослужащий взвода имеет право присутствовать на призыве и проводить отбор новобранцев в министерство обороны, для дальнейшего обучения военнослужащих.", category: "Устав МО" },
    { id: 209, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.1", text: "Военнослужащему взвода запрещено выдавать необоснованные наказания для военнослужащих.", category: "Устав МО" },
    { id: 210, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.2", text: "Военнослужащему взвода запрещено вести себя неподобающе офицеру, общаться грубо, оскорбительно, задевать честь и достоинство военнослужащих своего взвода и армии.", category: "Устав МО" },
    { id: 211, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.3", text: "Военнослужащему взвода запрещено выезжать с территории базы на тренировки, другие мероприятия связанные напрямую с деятельностью армии, без предупреждения старшего офицера на базе, если такого не имеется, то данный офицер должен оставить пометку в журнале тренировок и выезда с базы. Примеры доклада: /r Прошу разрешения для проведения выездной тренировки, с последующей транспортировкой военнослужащих вместо проведения тренировки. /r Прошу разрешения для выезда с базы автобуса, по причине: тренировка младшего состава.", category: "Устав МО" },
    { id: 212, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.4", text: "Военнослужащему взвода запрещено командовать военнослужащими других взводов, если поступил такой приказ от непосредственно командира взвода.", category: "Устав МО" },
    { id: 213, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.5", text: "Военнослужащему взвода запрещено находясь в отпуске, гражданской форме, порочить честь и достоинство своего взвода, так и себя самого, подставляя тем самым адмирала армии и его заместителей.", category: "Устав МО" },
    { id: 214, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.6", text: "Военнослужащему взвода запрещено проводить построения, лекции, тренировки, если был дан другой приказ от старшего офицера армии.", category: "Устав МО" },
    { id: 215, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.7", text: "Военнослужащему взвода запрещено игнорировать военнослужащих желающих пройти курс подготовки офицеров [КОП], сдать или пересдать устав, а так же принять присягу министерству обороны.", category: "Устав МО" },
    { id: 216, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.8", text: "Военнослужащему взвода запрещено проводить мероприятия, описанные в пункте 3.7., без фиксации выполненной работы со стороны принимающего их военнослужащего.", category: "Устав МО" },
    { id: 217, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.9", text: "Военнослужащему взвода запрещено быть некомпетентным в вопросах знания устава, присяги, специальных или общих лекций, тренировок проводимых для военнослужащих.[Обязаны знать большое число лекций и возможных тренировок, а не проводить одно и то же].", category: "Устав МО" },
    { id: 218, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.10", text: "Военнослужащему взвода запрещено игнорировать приказы и поручения командира взвода, если на то нет веской причины, которая не идёт в разрез с уставом министерства обороны.", category: "Устав МО" },
    { id: 219, law: "Устав МО", chapter: "Внутренний устав взвода общего назначения [ВОН]", point: "3.11", text: "Военнослужащему взвода запрещено предоставлять военнослужащим и иным лицам заведомо ложную или недостоверную информацию об армии, правилах прохождения службы, тренировках, лекциях и иных мероприятиях.", category: "Устав МО" },

    { id: 220, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "1", text: "Задача ВОиС обеспечить полноценность и неисчерпаемость склада армии. Правила вступают в силу с даты ее публикации. За грубое нарушение в поставках боеприпасов будет получать командир Взвода Охраны и Снабжения так же проводиться беседа с лидером.", category: "Устав МО" },
    { id: 221, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "2.1", text: "Колонна должна состоять минимум из 2х фур.", category: "Устав МО" },
    { id: 222, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "2.2", text: "Формирование колонны происходит: Для армии Лос-Сантос у КПП - 1, либо КПП - 2; Для армии Сан-Фиерро у КПП - 1; Для ТСР у КПП - 12.", category: "Устав МО" },
    { id: 223, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "2.3", text: "Разрешено проводить только одну поставку в час по 4 фуры для каждой армии.", category: "Устав МО" },
    { id: 224, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.1", text: "Хаммер или Камаз(без лишнего тюнинга, максимально разрешается 1 отбойник). Ведущая машина с охраной.", category: "Устав МО" },
    { id: 225, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.2", text: "Фуры с боекомплектами. Основная колонна.", category: "Устав МО" },
    { id: 226, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.3", text: "Хаммер. Ведомый и завершающий колонну транспорт. В некоторых случаях разрешено не использовать замыкающий транспорт.", category: "Устав МО" },
    { id: 227, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.4", text: "Армейский Maverick. [Не обязательно].", category: "Устав МО" },
    { id: 228, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.5", text: "Запрещается обгон ведущей машины.", category: "Устав МО" },
    { id: 229, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.6", text: "Запрещается обгон фур.", category: "Устав МО" },
    { id: 230, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.7", text: "Передвижение колонны осуществляется только ровным строем и по одной полосе.", category: "Устав МО" },
    { id: 231, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.8", text: "Запрещено подрезать сопровождение от министерства юстиции.", category: "Устав МО" },
    { id: 232, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "3.8.1", text: "Запрещено подрезать гражданские авто, если гражданское авто угрожает колоне то фура/хаммер имеет право подрезать авто.", category: "Устав МО" },
    { id: 233, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "4", text: "Задача хаммеров, вызвать вражеский огонь на себя. Путем прикрытия транспортом колонны.", category: "Устав МО" },
    { id: 234, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "4.1", text: "При нападении, конвой останавливается, выходит из машин и занимает круговую оборону, при помощи министерства юстиции. И при необходимости запрашивает подкрепление с базы.", category: "Устав МО" },
    { id: 235, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "4.2", text: "В критической ситуации, когда движение не может быть осуществлено, водители фур приступают к защите колонны.", category: "Устав МО" },
    { id: 236, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "4.3", text: "При уничтожении одной фуры, незамедлительно стоит поднять груз и загрузить в другую фуру.", category: "Устав МО" },
    { id: 237, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "4.4", text: "При транспортировке боеприпасов, обязательно иметь при себе оружие и рем. комплект.", category: "Устав МО" },
    { id: 238, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "5", text: "Каждый боец несет ответственность за груз и сохранность транспорта.", category: "Устав МО" },
    { id: 239, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "5.1", text: "Государственная [ПД] организация может предоставить транспорт и минимум двух человек для сопровождения.", category: "Устав МО" },
    { id: 240, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "5.2", text: "Сопровождение от министерства юстиции не обязательно.", category: "Устав МО" },
    { id: 241, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "5.6", text: "Если одному из депортаменов нужны срочно поставки, поставки может выполнить любая Армия. Вне зависимости от юриздикции.", category: "Устав МО" },
    { id: 242, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "6", text: "Распределение поставок среди МО в ПД. Армия г. Лос-Сантос: ЛСПД | РКШД. Армия г. Сан-Фиерро: ФБР | СФПД. Тюрьма Строгого Режима: РКШД | ЛВПД.", category: "Устав МО" },
    { id: 243, law: "Устав МО", chapter: "Регламент грузоперевозок", point: "7", text: "Действия при нападении на колонну: 1. Выйти из машин и устранить угрозу. 2. В случае потери одной из машин во время нападения - продолжить движение (обязательно нужно иметь доказательства).", category: "Устав МО" },

    { id: 244, law: "Устав МО", chapter: "Курс офицерской подготовки [КОП]", point: "1", text: "Что необходимо знать и иметь при сдаче КОП: Знать Устав Министерства Обороны; Знать присягу [Cдается посредством биндера]; Иметь высокий уровень строевой подготовки; Иметь высокий уровень физической подготовки.", category: "Устав МО" },
    { id: 245, law: "Устав МО", chapter: "Курс офицерской подготовки [КОП]", point: "2", text: "Перечень испытаний, необходимых для сдачи КОП: Принятие присяги; Сдача устава Министерства Обороны [C уклоном на обязанности офицеров]; Сдача строевой подготовки; Сдача полосы препятствий [На учебном полигоне]; Десантирование на территорию своей базы; Заплыв; Экстремальное вождение.", category: "Устав МО" },
    { id: 246, law: "Устав МО", chapter: "Курс офицерской подготовки [КОП]", point: "3", text: "КОП принимает военнослужащий взвода ВОН. [ 5+ ранг ]. Сдающему нужно скринить каждый пункт сдачи испытания. Экзаменатор обязан писать в рацию после каждого испытания: /r [ Взвод ] Имя и Фамилия (сдающего) успешно сдал Название испытания. В конце сдачи КОП, экзаменатор обязан написать: /r [Взвод] Имя и Фамилия успешно сдал КОП.", category: "Устав МО" },

    { id: 247, law: "Устав МО", chapter: "Проведение лекций и тренировок", point: "1", text: "Критерии составления и прочтения лекций: Лекция должна разъяснять основные моменты службы в Министерстве обороны. Лекция должна доносить до военнослужащих информацию из уставных документов. Лекция должна побуждать интерес к теме доносимого. Лекция должна быть разумных объемов. [В зависимости от темы. Не нужно копировать устав целиком и полностью]. Лекция должна быть написана заранее и заучена. [Биндер]. Лекция должна читаться в нормальном темпе и разборчивым голосом. [Интервал между сообщениями в биндере - 5 секунд] [Несоблюдение этого правила будет наказываться выговором в личное дело]. Запрещено проведений лекций по рации [/r , /rb].", category: "Устав МО" },
    { id: 248, law: "Устав МО", chapter: "Проведение лекций и тренировок", point: "2", text: "Критерии составления и проведения тренировок: На тренировках разрешена отработка навыков стрельбы из пневматического оружия до снятия бронежилета. [системно /duel]. Тренировка может быть направлена на повышение военно-специальной подготовленности военнослужащих. Тренировка может быть направлена на совершенствование боевой слаженности воинских подразделений. Тренировка может быть направлена на развитие и совершенствование физических качеств. Тренировка должна способствовать воспитанию психической устойчивости и морально-волевых качеств; Тренировка не должна повлечь за собой нарушение действующих уставных документов Министерства Обороны со стороны военнослужащих. Тренировка должна иметь быть заранее спланированной и иметь отработанную форму проведения. [Не должна быть однотипной и банальной]. Минимальный интервал между обязательными построениями состава - 20 минут [исключения - ГРП и теракты].", category: "Устав МО" },

    { id: 249, law: "Устав МО", chapter: "Использование тегов в рации", point: "1", text: "В Организациях разрешены только тэги, устанавливаемые через команду /settag.", category: "Устав МО" },
    { id: 250, law: "Устав МО", chapter: "Использование тегов в рации", point: "2", text: "Тэги устанавливаются исключительно на русском языке.", category: "Устав МО" },
    { id: 251, law: "Устав МО", chapter: "Использование тегов в рации", point: "3", text: "Тэги устанавливаются по принципу принадлежности игрока взводу/отделу/подразделению и занимаемой им должности в этом взводе/отделе/подразделение.", category: "Устав МО" },
    { id: 252, law: "Устав МО", chapter: "Использование тегов в рации", point: "4", text: "Устанавливаемые тэги не должны противоречить РП процессу.", category: "Устав МО" },
    { id: 253, law: "Устав МО", chapter: "Использование тегов в рации", point: "5", text: "Запрещены тэги, в которых используется нецензурная лексика, либо которые могут кого либо оскорбить.", category: "Устав МО" },
    { id: 254, law: "Устав МО", chapter: "Использование тегов в рации", point: "6", text: "Следящая администрация вправе потребовать изменения/удаления определенных тэгов.", category: "Устав МО" },

    { id: 255, law: "Устав МО", chapter: "Территории военных баз", point: "1", text: "Сотрудникам гос структур/гражданам запрещено находится на Жёлтой зоне без предъявления документов военнослужащему армии по первой просьбе, в крайнем случае будет ликвидация данного человека.", category: "Устав МО" },
    { id: 256, law: "Устав МО", chapter: "Территории военных баз", point: "1.1", text: "Военнослужащий имеет полное право, увидев документ гражданина штата, попросить его отойти от КПП на 10 метров, для сохранения безопасности воинской части, в крайнем случае будет ликвидация данного человека.", category: "Устав МО" },
    { id: 257, law: "Устав МО", chapter: "Территории военных баз", point: "2", text: "Сотрудникам гос структур/гражданам запрещено находится на Красной зоне, даже при предъявлении документов военнослужащему армии, в этом случае военнослужащий имеет право на ликвидацию данного человека. Исключение: Сотрудники Министерства Юстиции в случае ЧС/запроса в департамент.", category: "Устав МО" },
    { id: 258, law: "Устав МО", chapter: "Территории военных баз", point: "3", text: "На Красной зоне имеют полное право находится сотрудники Министерства Юстиции, при Чрезвычайных ситуаций, при исполнении или задержании человека находящийся на данной территории.", category: "Устав МО" },
    { id: 259, law: "Устав МО", chapter: "Территории военных баз", point: "3.1", text: "Нахождения сотрудников Министерства Юстиции на территории объекта Министерства Обороны без причины - строго воспрещено!", category: "Устав МО" },
    { id: 260, law: "Устав МО", chapter: "Территории военных баз", point: "3.2", text: "Нахождение сотрудников Министерства Юстиции на территории объекта Министерства Обороны в маске запрещено. Разрешается в случае ЧС на объекте.", category: "Устав МО" },
    { id: 261, law: "Устав МО", chapter: "Территории военных баз", point: "3.3", text: "Сотрудник Министерства Юстиции обязан предъявить удостоверение любому военнослужащему Министерства Обороны. Любой военнослужащий имеет право спросить удостоверение только на КПП. На самой территории базы, только военнослужащий офицерского состава имеет право спросить удостоверение.", category: "Устав МО" },
    { id: 262, law: "Устав МО", chapter: "Территории военных баз", point: "3.4", text: "Облеты военных баз сотрудниками Министерства Юстиции, проводятся только с разрешения Офицерского состава Военной базы.", category: "Устав МО" },
    { id: 263, law: "Устав МО", chapter: "Территории военных баз", point: "3.5", text: "Доступ на территории военных баз сотрудники Министерства Юстиции без разрешения офицерского состава и проверки документов запрещён. Сотрудники SWAT и МЮ в целом имеют доступ на базу только в случае чрезвычайной ситуации и проверки военной базы на ЧС. Перед въездом на военную базу, сотрудники SWAT и МЮ обязаны предупредить об этом через волну департамента и запросить одобрение на въезд. Если сотрудник МЮ/SWAT выходит на связь с определённой армией и ему никто не отвечает, то ему запрещено самовольно проникать на территорию военной базы без одобрения офицерского состава армии.", category: "Устав МО" },
    { id: 264, law: "Устав МО", chapter: "Территории военных баз", point: "4", text: "Губернатор штата, Вице-Губернатор, а также их сопровождение имеют право находиться на территории любого военного объекта без особого разрешения, при предъявлении документов, согласно уставу Министерства Обороны.", category: "Устав МО" },
    { id: 265, law: "Устав МО", chapter: "Территории военных баз", point: "5", text: "Сотрудникам Государственных Структур запрещено находится на Красной зоне (исключение: пункт 3, 4).", category: "Устав МО" },
    { id: 266, law: "Устав МО", chapter: "Территории военных баз", point: "6", text: "Сотрудникам Министерства Здравоохранения разрешается нахождение на Красной зоне без предъявления документов военнослужащему армии, в случаем оказания Первой Медицинской Помощи. В остальных случаях посещения территории военных баз-обязаны предупредить об этом через волну департамента и запросить одобрение на въезд.", category: "Устав МО" },
    { id: 267, law: "Устав МО", chapter: "Территории военных баз", point: "7", text: "Данное правило действуют независимо на всех жителей Штата.", category: "Устав МО" },
    { id: 268, law: "Устав МО", chapter: "Территории военных баз", point: "8", text: "За нарушение данных правил гражданину/сотруднику гос. структуры полагается Уголовная ответственность.", category: "Устав МО" },
    { id: 269, law: "Устав МО", chapter: "Территории военных баз", point: "9", text: "За ликвидацию сотрудников гос. структур/гражданина находившиеся на Зелёной зоне без весомой причины военнослужащим данной армии, полагается наказанием (от выговора до jail 60-120)", category: "Устав МО" },
    { id: 270, law: "Устав МО", chapter: "Территории военных баз", point: "10", text: "За ликвидацию сотрудников гос. структур/гражданина находившиеся на Жёлтой зоне с предъявлением документов без весомой причины военнослужащим данной армии, полагается наказанием (от выговора до jail 60-120)", category: "Устав МО" },
    { id: 271, law: "Устав МО", chapter: "Территории военных баз", point: "11", text: "Военнослужащему запрещено требовать предъявления документов у лиц, находящихся исключительно в Зелёной зоне, если отсутствуют основания для проверки, предусмотренные настоящими правилами.", category: "Устав МО" },
    { id: 272, law: "Устав МО", chapter: "Территории военных баз", point: "12", text: "Любые изменения/нововведения в данное правило должно быть согласовано с руководством Министерства Обороны.", category: "Устав МО" },
    { id: 273, law: "Устав МО", chapter: "Территории военных баз", point: "12.1", text: "Любые изменения/нововведения в данное правило без согласования руководством Министерства Обороны, не является действительным.", category: "Устав МО" },
    { id: 274, law: "Устав МО", chapter: "Территории военных баз", point: "12.1.1", text: "На Оранжевой зоне запрещено находиться гражданским лицам и сотрудникам государственных структур без весомой причины. По требованию военнослужащего нарушитель обязан покинуть территорию. В случае отказа после установленного предупреждения военнослужащий вправе применить предусмотренные правилами меры для пресечения нарушения. Открытие огня допускается только при наличии оснований, предусмотренных Единым уставом МО.", category: "Устав МО" },
    { id: 275, law: "Устав МО", chapter: "Территории военных баз", point: "13", text: "В случае отказа покинуть территорию военкомата после трёх предупреждений военнослужащий вправе применить предусмотренные правилами меры для пресечения нарушения. Применение огнестрельного оружия допускается только при наличии оснований, предусмотренных Единым уставом МО. Действия военнослужащего должны быть зафиксированы на видеозапись. (с /time или включенной системной /bodycamera)", category: "Устав МО" },

    { id: 276, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "1", text: "Использовать личное Т/С разрешается только с ранга Подполковник/Контр-адмирал[8] в служебных целях.", category: "Устав МО" },
    { id: 277, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "2", text: "Служебными целями могут считаться: выезд в военкомат, поездки для подписания договоров/собрания/деловые встречи и т.п. (за бессмысленные катания по базе/карте последует наказание).", category: "Устав МО" },
    { id: 278, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "3", text: "Т/С военнослужащего должно выглядеть подобающе: строгая расцветка, отсутствие винилов, NonRP и ДБ-тюнинга (ковш, черепа, доски). Исключение: на авто может быть специальный кенгурятник.", category: "Устав МО" },
    { id: 279, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "3.1", text: "Разрешается использовать только легковое авто премиального класса. Пример: Mercedes, Cadillac, Rolls Royce, Maybach и т.д. Исключение: разрешение ГС/ЗГСа.", category: "Устав МО" },
    { id: 280, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "3.2", text: "Разрешены любые технические улучшения.", category: "Устав МО" },
    { id: 281, law: "Устав МО", chapter: "Правила использования личного авто руководством", point: "4", text: "Машина должна быть припаркована согласно уставу. За нарушение выше перечисленных пунктов лидер может получить балловое взыскание, при повторном нарушении - устное предупреждение.", category: "Устав МО" },

    { id: 282, law: "Устав МО", chapter: "Правила использования военных дронов", point: "1", text: "Военные дроны предназначены для патрулирования территории военной базы путем облета, защиты ее от нападения при помощи спусковой гранаты. Военный дрон не предназначен для вылета на нем за пределы территории базы, игр и веселья.", category: "Устав МО" },
    { id: 283, law: "Устав МО", chapter: "Правила использования военных дронов", point: "2", text: "За неправильное использование дронов предусмотрены следующие наказания: Убийство дроном без причины, помеха дроном, вылет дроном за пределы базы - JAIL на 120 минут. Последующее нарушение правил- WARN.", category: "Устав МО" },

    { id: 284, law: "Устав МО", chapter: "Примечания к правилам взаимодействия с Министерством Юстиции", point: "21.6", text: "В случае любого взаимодействия или задержания сотрудниками МЮ на территории военного объекта, военнослужащий обязан предоставить документ, удостоверяющий личность (паспорт), либо служебное удостоверение, чтобы официально доказать, что он является законным военнослужащим данной Армии или Тюрьмы Строгого Режима (ТСР). При уклонении от проверки документов сотрудники полиции вправе провести задержание до выяснения обстоятельства с последующим докладом руководству ВЧ.", category: "устав ТСР" },
    
    // ============================================================
    // ФЕДЕРАЛЬНОЕ ПОСТАНОВЛЕНИЕ ШТАТА СПЭЙС
    // ============================================================
    { id: 442, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.1", text: "Целью настоящего Федерального Постановления является установление общих положений и правил для регулирования различных видов деятельности в штате Спэйс.", category: "фп" },
    { id: 443, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.2", text: "Данный раздел определяет область применения настоящего Федерального Постановления и его роли в создании и поддержании правового порядка, общественной безопасности и благосостояния граждан штата Спэйс.", category: "фп" },
    { id: 444, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.3", text: "Федеральное Постановление определяет обязанности, привилегии, а также ограничения для всех государственных организаций.", category: "фп" },
    { id: 445, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.4", text: "Действие настоящего Федерального Постановления распространяется на все государственные организации, регулирующие свою деятельность в соответствии с установленными нормами и положениями.", category: "фп" },
    { id: 446, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.5", text: "Взыскание назначается на принципах законности, доказанности вины, индивидуального подхода, справедливости и соразмерности. Выбирается наименее строгое взыскание, достаточное для прекращения нарушения и предупреждения его повторения. Более строгое взыскание допускается с учётом тяжести, последствий и обстоятельств нарушения; причины выбора указываются в решении.", category: "фп" },
    { id: 447, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.6", text: "При превышении должностных полномочий, вердикт уполномоченного лица может быть отменен в рамках судебного процесса, федеральным правительством, или постановлением генеральной прокуратуры.", category: "фп" },
    { id: 448, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.7", text: "При превышении должностных полномочий, вердиктом федерального правительства, судебным решением или постановление генеральной прокуратуры, в личное дело лица может быть занесено дисциплинарное взыскание.", category: "фп" },
    { id: 449, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.8", text: "При выборе взыскания учитываются характер нарушения, вина, вред и опасность, обстоятельства и длительность нарушения, его повторность, поведение сотрудника после нарушения, смягчающие и отягчающие обстоятельства. Должность, личные отношения и ведомство сами по себе не влияют на строгость взыскания.", category: "фп" },
    { id: 450, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.9", text: "Устное предупреждение применяется только если предусмотрено санкцией статьи, за впервые совершённое малозначительное нарушение, которое прекращено и последствия которого устранены, если нет существенного вреда, ограничения прав, срыва задачи, реальной угрозы жизни или здоровью и отягчающих обстоятельств. Признание вины не требуется; несогласие с обвинением не усиливает взыскание.", category: "фп" },
    { id: 451, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.10", text: "Устное предупреждение не применяется при вреде жизни или здоровью либо угрозе такого вреда, существенном ограничении прав или материальном ущербе, умышленном срыве процессуальных действий или спецоперации, сокрытии нарушения, подделке доказательств, давлении на участников или повторности по статье 1.12. В этих случаях назначается другое взыскание из санкции статьи, но не обязательно максимальное.", category: "фп" },
    { id: 452, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.11", text: "Объявляя предупреждение, уполномоченное лицо представляется, называет статью и действия сотрудника, предоставляет возможность дать объяснение, разъясняет взыскание и порядок обжалования, фиксирует объявление на видео и вносит его в реестр. Замечание или требование прекратить нарушение взысканием не считается.", category: "фп" },
    { id: 453, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.12", text: "Повторным считается новое однородное нарушение в течение 72 часов после объявления и регистрации предыдущего взыскания. Однородность определяется нарушенной обязанностью или запретом, а не только номером статьи. Продолжающееся нарушение считается одним эпизодом; отменённое взыскание не учитывается. По истечении 72 часов предупреждение не учитывается для повторности, но хранится в установленном порядке.", category: "фп" },
    { id: 454, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.13", text: "Смягчающими обстоятельствами являются добровольное прекращение или сообщение о нарушении, содействие проверке, предотвращение или устранение последствий, отсутствие ранее установленных однородных нарушений и иные обстоятельства, снижающие тяжесть проступка. Они учитываются только при выборе взыскания, предусмотренного статьёй.", category: "фп" },
    { id: 455, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.14", text: "Отягчающими обстоятельствами являются повторность, продолжение нарушения после законного требования, вовлечение подчинённых с использованием должности, корыстная заинтересованность, помехи экстренной помощи или спецоперации, сокрытие нарушения, подделка доказательств и давление на участников. Признак состава нарушения повторно не учитывается.", category: "фп" },
    { id: 456, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.15", text: "Обязательная последовательность взысканий не устанавливается. За тяжёлое нарушение строгое взыскание может быть назначено при первом эпизоде, если оно предусмотрено статьёй и обосновано. За малозначительное нарушение, соответствующее статье 1.9, назначается предусмотренное санкцией предупреждение. Повторность не влечёт автоматического увольнения или понижения; порядок перечисления санкций не определяет очерёдность.", category: "фп" },
    { id: 457, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.16", text: "За один проступок назначается одно дисциплинарное взыскание. Если специальная норма полностью охватывает действие, повторное наказание по общей норме не применяется. Самостоятельные нарушения оцениваются отдельно. Дисциплинарное взыскание не исключает уголовную или административную ответственность. Чёрный список применяется только в предусмотренных законом случаях и порядке.", category: "фп" },
    { id: 458, law: "Федеральное постановление", chapter: "Глава I. Цель и область применения", point: "1.17", text: "Решение о взыскании указывает обстоятельства нарушения, статью, доказательства, оценку объяснений, выбранное взыскание, причины отказа от менее строгого и порядок обжалования. Взыскание назначается только в пределах полномочий; при их отсутствии материалы передаются компетентному органу. Отсутствие полномочий объявить предупреждение само по себе не оправдывает более строгое взыскание.", category: "фп" },

    { id: 459, law: "Федеральное постановление", chapter: "Глава II. Понятия и определения", point: "2.1", text: "В рамках настоящего Федерального Постановления применяются следующие понятия и определения: (a) Федеральное Постановление штата Спэйс - нормативно-правовой акт, имеющий обязательную силу для всех государственных организаций, их сотрудников, находящихся на территории штата Спэйс; (b) Граждане - физические лица, обладающие гражданством Соединенных Штатов Америки, проживающие в штате Спэйс; (c) Сотрудник - физическое лицо, которое работает в государственной организации; (d) Руководство(Руководитель/Лидер) - физическое лицо, в подчинение которого находится государственная организация; (e) Экспресс-тест (полевой химический анализ) - метод мгновенного определения химического состава вещества с помощью портативного анализатора, дающий результат в течение нескольких секунд без отправки образца в лабораторию; (f) Фаза отравления - установление в мед карте гражданина отметки о наличии/степени запрещенных веществ в организме.", category: "фп" },

    { id: 460, law: "Федеральное постановление", chapter: "Глава III. Органы государственной власти", point: "3.1", text: "Для эффективного функционирования и реализации положений настоящего Федерального Постановления действуют следующие органы государственной власти: (a) Федеральное Бюро Расследований штата Спэйс - осуществляет контроль за исполнением настоящего Федерального Постановления; (b) Губернатор штата Спэйс, Вице-Губернатор штата Спэйс - осуществляют контроль за исполнением настоящего Федерального Постановления; (c) Офис Генеральной прокуратуры штата Спэйс - осуществляет надзор за исполнением настоящего Федерального Постановления; (d) Судейская Коллегия штата Спэйс - осуществляет контроль за исполнением настоящего Федерального Постановления путем рассмотрения исковых заявлений.", category: "фп" },

    { id: 461, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.1", text: "Сотрудникам запрещено использовать служебное положение в личных целях. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Увольнение; (b) Понижение.", category: "фп" },
    { id: 462, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.2", text: "Сотрудникам запрещено проявлять неуважение к гражданским или должностным лицам. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Устное предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение.", category: "фп" },
    { id: 463, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.3", text: "Сотрудникам запрещено допускать грубое, пренебрежительное или унижающее честь и достоинство обращение по отношению к гражданам и должностным лицам: (a) Устное предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение; (e) Увольнение. Примечание 1. Под нарушение настоящей статьи подпадает, в том числе, использование фамильярного обращения (\"ты\") в ситуациях, не предусматривающих таковой формы общения, если это противоречит служебной субординации или может быть воспринято как проявление неуважения. Примечание 2. При квалификации нарушения учитывается контекст ситуации. Обращение на \"ты\" не является нарушением, если оно продиктовано общепринятыми нормами общения в конкретной обстановке или не несет оскорбительного умысла.", category: "фп" },
    { id: 464, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.4", text: "Сотрудникам запрещено открывать огонь из огнестрельного оружия, электрошокера без причины. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение.", category: "фп" },
    { id: 465, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.5", text: "Сотрудникам запрещено иметь какие-либо связи с преступным миром. Исключение: Информаторы, агент ФБР под прикрытием. (a) Увольнение; (b) Занесение в ЧС.", category: "фп" },
    { id: 466, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.6", text: "Сотрудникам запрещено заниматься своими личными делами в рабочее время. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Устное предупреждение; (b) Выговор; (c) Понижение; (d) Специальный выговор.", category: "фп" },
    { id: 467, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.7", text: "Сотрудникам запрещено находиться на различных видах торговых предприятий, игорных предприятиях и иных общественных местах в служебной форме, если это не предусмотрено внутренними регламентирующими документами организаций. За нарушение данного пункта в отношении сотрудника может быть применена одна из санкций: (a) Предупреждение; (b) Выговор; (c) Специальный выговор; (d) Увольнение.", category: "фп" },
    { id: 468, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.8", text: "Сотрудникам Министерства Юстиции, Министерства Обороны запрещено вмешиваться в специальные операции без предварительного согласования с куратором данной специальной операции. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Понижение; (b) Увольнение.", category: "фп" },
    { id: 469, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.9", text: "Запрещено нарушать установленные внутренними регламентирующими документами вашей организации правила строя. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Устное предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение; (e) Увольнение.", category: "фп" },
    { id: 470, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.10", text: "Сотрудникам Министерства Юстиции запрещено объявлять в розыск людей без причин или по статьям, которые не предусмотрены уголовным кодексом штата Спэйс. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Понижение; (b) Увольнение.", category: "фп" },
    { id: 471, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.11", text: "Сотрудникам Министерства Юстиции запрещено выносить преступника из списка подозреваемых без причины. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Понижение; (b) Увольнение; (c) Занесение в ЧС.", category: "фп" },
    { id: 472, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.12", text: "Сотрудникам Министерства Обороны запрещено находится за пределами своей военной части. Исключение: Разрешение от офицерского состава организации, тренировка, специальная операция, поставка амуниции. (a) Устное предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение; (e) Увольнение.", category: "фп" },
    { id: 473, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.13", text: "Сотрудникам запрещено каким - либо способом провоцировать других сотрудников. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Устное предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение.", category: "фп" },
    { id: 474, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.14", text: "Сотрудникам запрещено использовать служебное транспортное средство в личных целях. За нарушение данного пункта в отношении сотрудника может быть применена одна из санкций: (a) Предупреждение; (b) Выговор; (c) Специальный выговор.", category: "фп" },
    { id: 475, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.15", text: "Сотрудникам запрещено использовать личное транспортное средство находясь при исполнении служебных обязанностей. Исключение: сотрудники Правительства, сотрудники Офиса Генеральной прокуратуры, сотрудники судейской коллегии, сотрудники коллегии адвокатуры или транспортное средство зарегистрировано в реестре немаркированных автомобилей. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Устное предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение.", category: "фп" },
    { id: 476, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.16", text: "Сотрудникам запрещено обманывать собственное руководство. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Увольнение; (b) Выговор; (c) Специальный выговор.", category: "фп" },
    { id: 477, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.17", text: "Сотрудники Министерства Юстиции обязаны соблюдать юрисдикцию своего департамента при выполнении своих служебных обязанностей. Исключение: общая юрисдикция на договорной основе с другими департаментами, федеральное бюро расследований штата Спэйс, SWAT. За нарушение данного пункта в отношении сотрудника может быть применен выговор.", category: "фп" },
    { id: 478, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.18", text: "Сотрудникам запрещено употреблять спиртные напитки в рабочее время. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Устное предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение; (e) Увольнение.", category: "фп" },
    { id: 479, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.19", text: "Сотрудникам федерального бюро расследования, которые состоят на 8 порядковой должности, запрещается снимать выговор без обоснованных на то причин. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Выговор; (b) Понижение; (c) Увольнение.", category: "фп" },
    { id: 480, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.20", text: "Сотрудникам государственных структур запрещено превышать или злоупотреблять своими должностными полномочиями. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Выговор; (b) Понижение; (c) Увольнение; (d) Занесение в ЧС.", category: "фп" },
    { id: 481, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.21", text: "Сотрудник который состоит в гос. фракции обязан иметь мед. карту без следующих пометок: прохождение лечения в психиатрическом учреждении, диагноз, свидетельствующий о том, что у человека в карте есть параметр \"Фаза отравления\" \"20\" и больше. За нарушения данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Выговор; (b) Специальный выговор; (c) Увольнение. Примечание 1. Выявление фазы отравления осуществляется на месте сотрудниками Министерства Юстиции, с соблюдением закона о судебно-медицинской экспертизе штата Спэйс статьи 2.5. Примечание 2. Отказ от прохождения теста на выявление фазы отравления, приравнивается к нарушению и наказывается в соответствии с данной статьей.", category: "фп" },
    { id: 482, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.22", text: "За нарушения Дресс-Кода организации сотруднику может быть применена одна из следующих санкций: (a) Предупреждение; (b) Выговор.", category: "фп" },
    { id: 483, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.23", text: "Запрещена халатность сотрудника, не повлёкшая за собой материальный либо иной значимый ущерб: (a) Устное предупреждение; (b) Выговор; (c) Понижение.", category: "фп" },
    { id: 484, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.24", text: "Запрещена халатность сотрудника, влекущая за собой ущерб в виде: 1) Тяжкого вреда здоровья; 2) Смерти человека; 3) Игнорирование пресечения явных нарушений действующего законодательства штата Спэйс. (a) Выговор; (b) Увольнение; (c) Занесение в ЧС; (d) Спец. выговор.", category: "фп" },
    { id: 485, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.25", text: "За сон в рабочее время, сотруднику, находящегося в форме, может быть применена одна из следующих санкций: (a) Предупреждение; (b) Выговор; (c) Специальный выговор. Примечание 1. Перед применением любой из указанных санкций необходимо показать сотруднику удостоверение, представиться и предоставить 2 минуты на ответ.", category: "фп" },
    { id: 486, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.26", text: "Запрещено нарушение внутреннего устава организации, а также законов связанных с деятельностью организации, сотруднику может быть применена одна из следующих санкций: (a) Устное предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение; (e) Увольнение.", category: "фп" },
    { id: 487, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.27", text: "Запрещено нарушение административного кодекса штата: (a) Предупреждение; (b) Выговор.", category: "фп" },
    { id: 488, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.28", text: "Запрещено задержание неприкосновенного лица без соответствующего ордера: (a) Понижение; (b) Увольнение.", category: "фп" },
    { id: 489, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.29", text: "Запрещено проникновение на закрытую территорию: (a) Устное предупреждение; (b) Выговор.", category: "фп" },
    { id: 490, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.30", text: "Запрещено проводить учебные мероприятия (лекции, тренировки и т.п.) с интервалом менее 20 минут между ними. Сотрудник, ответственный за организацию и проведение данных мероприятий обязан обеспечить перерыв продолжительностью не менее 20 минут между окончанием одного мероприятия и началом следующего. За нарушение данной статьи к сотруднику, проводившему мероприятия с нарушением установленного интервала, может быть применена одна из следующих санкций: (a) Устное предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение в должности; (e) Увольнение (при систематическом нарушении, повлекшем за собой жалобы или снижение эффективности подготовки). Примечание 1. Экстренные случаи, требующие немедленного информирования личного состава (чрезвычайные ситуации, боевые тревоги и т.п.), допускают проведение мероприятий без соблюдения указанного интервала по решению руководителя организации.", category: "фп" },
    { id: 491, law: "Федеральное постановление", chapter: "Глава IV. Ограничения для сотрудников", point: "4.31", text: "Запрещено создавать помеху сотрудникам не силовых структур при исполнении ими служебных обязанностей. За нарушение данной статьи к сотруднику, проводившему мероприятия с нарушением установленного интервала, может быть применена одна из следующих санкций: (a) Устное предупреждение; (b) Выговор; (c) Понижение в должности; (d) Увольнение. Примечание 1. Помехой считается любое действие, создающее помеху в работе сотрудника, включая, но не ограничиваясь предложением услуг гражданину, что уже работает с другим сотрудником, перебиванием сотрудника, попытками убедить граждан в некомпетентности сотрудника.", category: "фп" },

    { id: 492, law: "Федеральное постановление", chapter: "Глава V. Права сотрудников Офиса Генерального прокурора в отношении других организаций", point: "5.1", text: "Запрещено обыскивать сотрудников Офиса Генеральной прокуратуры штата Спэйс. Исключение: Сотрудник прокуратуры который нарушает уголовный кодекс. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Выговор; (b) Специальный выговор; (c) Понижение; (d) Увольнение.", category: "фп" },
    { id: 493, law: "Федеральное постановление", chapter: "Глава V. Права сотрудников Офиса Генерального прокурора в отношении других организаций", point: "5.2", text: "Сотрудник Офиса Генеральной прокуратуры имеет право потребовать любого государственного служащего, если он нарушает законодательство, оставаться на месте до прибытия сотрудников Министерства Юстиции. За нарушение данного пункта в отношении сотрудника применяется дисциплинарное взыскание в виде увольнения.", category: "фп" },
    { id: 494, law: "Федеральное постановление", chapter: "Глава V. Права сотрудников Офиса Генерального прокурора в отношении других организаций", point: "5.3", text: "Любой сотрудник обязан по первому требованию сотрудника Офиса Генеральной прокуратуры, при предъявлении удостоверения/бейджа сотрудника Офиса Генеральной прокуратуры, назвать свои настоящие Имя Фамилию, должность, позывной, и по требованию сотрудника Офиса Генеральной Прокуратуры показать свой паспорт или удостоверение. Примечание 1. При отсутствии одного из документов (паспорта или удостоверения) сотрудник обязан предъявить второй имеющийся документ.", category: "фп" },
    { id: 495, law: "Федеральное постановление", chapter: "Глава V. Права сотрудников Офиса Генерального прокурора в отношении других организаций", point: "5.4", text: "Сотрудник Офиса Генеральной прокуратуры имеет право осуществить отстранение сотрудников при выявлении нарушений статей, предусматривающих увольнение из организации, за исключением лиц, обладающих степенью неприкосновенности. Неправомерное или неоправданное приостановление исполнения полномочий того или иного лица со стороны Офиса Генеральной прокуратуры можно обжаловать в судебном порядке.", category: "фп" },
    { id: 496, law: "Федеральное постановление", chapter: "Глава V. Права сотрудников Офиса Генерального прокурора в отношении других организаций", point: "5.5", text: "Сотрудник Офиса Генеральной прокуратуры имеет право осуществить выдачу выговора сотрудникам, занимающим должности с первой по восьмую порядковую, при выявлении нарушений статей, предусматривающих выговор из организации.", category: "фп" },
    { id: 497, law: "Федеральное постановление", chapter: "Глава V. Права сотрудников Офиса Генерального прокурора в отношении других организаций", point: "5.6", text: "Генеральный прокурор вправе самостоятельно получать со склада ФБР и носить служебное огнестрельное оружие в целях обеспечения личной безопасности и исполнения служебных обязанностей.", category: "фп" },
    { id: 498, law: "Федеральное постановление", chapter: "Глава V. Права сотрудников Офиса Генерального прокурора в отношении других организаций", point: "5.6", text: "Генеральный прокурор вправе самостоятельно получать со склада ФБР и носить служебное огнестрельное оружие в целях обеспечения личной безопасности и исполнения служебных обязанностей.", category: "фп" },
    { id: 499, law: "Федеральное постановление", chapter: "Глава V. Права сотрудников Офиса Генерального прокурора в отношении других организаций", point: "5.7", text: "Наличие служебного оружия не наделяет Генерального прокурора дополнительными полномочиями сотрудника ФБР и не предоставляет ему право осуществлять задержания, обыски или иные полицейские мероприятия исключительно на основании данной статьи.", category: "фп" },
    { id: 500, law: "Федеральное постановление", chapter: "Глава V. Права сотрудников Офиса Генерального прокурора в отношении других организаций", point: "5.8", text: "Применение служебного оружия допускается исключительно в случаях необходимой обороны, защиты жизни и здоровья граждан, а также при наличии непосредственной угрозы жизни Генерального прокурора.", category: "фп" },
    { id: 501, law: "Федеральное постановление", chapter: "Глава V. Права сотрудников Офиса Генерального прокурора в отношении других организаций", point: "5.9", text: "Генеральному прокурору запрещается использовать форменное обмундирование подразделения SWAT ФБР, за исключением случаев официального участия в специальной операции совместно с подразделением SWAT.", category: "фп" },

    { id: 502, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.1", text: "Запрещено обыскивать сотрудников федерального бюро расследований. Исключение: Нарушение сотрудником ФБР уголовного кодекса, проведение проверки от Офиса Генеральной прокуратуры. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение; (e) Увольнение.", category: "фп" },
    { id: 503, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.2", text: "Сотрудник федерального бюро расследований имеет право задержать любого государственного служащего если он нарушает законодательство, или по постановлению суда/прокуратуры.", category: "фп" },
    { id: 504, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.3", text: "Сотрудник федерального бюро расследований имеет право вызвать любого государственного служащего в офис федерального бюро расследований с разъяснением причины вызова по рации департамента. Если будет доказана неправомерность вызова, то к сотруднику ФБР, который осуществил вызов будет применена статья 8 настоящего Федерального Постановления. Исключение: непосредственно принадлежащий к государственному управлению сотрудник, неприкосновенные лица.", category: "фп" },
    { id: 505, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.4", text: "Сотрудникам гос. структур запрещено исполнять незаконные требования сотрудников федерального бюро расследований. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Предупреждение; (b) Выговор; (c) Специальный выговор; (d) Понижение; (e) Увольнение.", category: "фп" },
    { id: 506, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.5", text: "Любой сотрудник обязан по первому требованию сотрудника федерального бюро расследований, при предъявлении жетона/удостоверения сотрудника федерального бюро расследований, назвать свои настоящие имя фамилию/Либо показать паспорт (В зависимости от того, что требует сотрудник ФБР), должность/Либо показать удостоверение (В зависимости от того, что требует сотрудник ФБР), позывной (При наличии), и по требованию сотрудника федерального бюро расследований показать полный комплект документов. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Предупреждение; (b) Специальный выговор.", category: "фп" },
    { id: 507, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.6", text: "Сотрудник федерального бюро расследований имеет право проводить обыск любого сотрудника при наличии оснований для проверки за исключением сотрудников Офиса Генеральной прокуратуры, а также лиц, имеющих неприкосновенность.", category: "фп" },
    { id: 508, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.7", text: "Сотруднику запрещено раскрывать сотрудника федерального бюро расследований под маскировкой при любых обстоятельствах. За нарушение данного пункта в отношении сотрудника может быть применена одна из следующих санкций: (a) Понижение; (b) Увольнение.", category: "фп" },
    { id: 509, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.8", text: "Сотрудникам государственных организаций запрещено находиться на территории или в офисе федерального бюро расследований без вызова или в сопровождении седьмой порядковой должности федерального бюро расследований и старше. Перед въездом на территорию данный сотрудник обязан уведомить сотрудника федерального бюро расследований который осуществляет вызов в волну департамента. Исключение: присутствие руководства при допросе сотрудника своей организации; сотрудники прокуратуры. За нарушение данного пункта в отношении сотрудника может быть применено увольнение.", category: "фп" },
    { id: 510, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.9", text: "Руководство федерального бюро расследований имеет право осуществить отстранение сотрудника в случае выявления нарушений статей, предусматривающих увольнение из организации, за исключением лиц, обладающих любой степенью неприкосновенности. Неправомерное или неоправданное приостановление исполнения полномочий того или иного лица со стороны федерального бюро расследований можно обжаловать в судебном порядке. Примечание 1. Руководство федерального бюро расследований при выдаче дисциплинарного взыскания в виде увольнения с занимаемой должности, вправе не осуществлять вызов руководства сотрудника и/или сотрудника Офиса Генерального прокурора в случае, если процедура задержания в отношении сотрудника, которому выносится данное взыскание, не проводилась.", category: "фп" },
    { id: 511, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.10", text: "Сотрудник федерального бюро расследований, занимающий не менее шестой порядковой должности, имеет право осуществить отстранение сотрудников, занимающих должности с первой по четвертую порядковую, при выявлении нарушений статей, предусматривающих увольнение из организации, за исключением лиц, обладающих любой степенью неприкосновенности. Неправомерное или неоправданное приостановление исполнения полномочий того или иного лица со стороны федерального бюро расследований можно обжаловать в судебном порядке. Примечание 1. Сотрудник федерального бюро расследований, занимающий не менее шестой порядковой должности при выдаче дисциплинарного взыскания сотруднику с первой по четвертой порядковой должности в виде увольнения с занимаемой должности вправе не осуществлять вызов руководства сотрудника и/или сотрудника Офиса Генерального прокурора в случае, если процедура задержания в отношении сотрудника, которому выносится данное взыскание, не проводилась.", category: "фп" },
    { id: 512, law: "Федеральное постановление", chapter: "Глава VI. Права сотрудников Федерального бюро расследований в отношении других организаций", point: "6.11", text: "Сотрудник федерального бюро расследований, занимающий не менее шестой порядковой должности, имеет право осуществить выдачу спец. выговора сотрудникам, занимающим должности с первой по восьмую порядковую, при выявлении нарушений статей, предусматривающих спец. выговор, за исключением лиц, обладающих любой степенью неприкосновенности. Неправомерное или неоправданное приостановление исполнения полномочий того или иного лица со стороны федерального бюро расследований можно обжаловать в судебном порядке.", category: "фп" },

    { id: 513, law: "Федеральное постановление", chapter: "Глава VII. Дополнительные положения", point: "7.1", text: "Сотрудник федерального бюро расследований, занимающий не менее девятой порядковой должности, имеет право осуществить занесение в Чёрный Список государственной организации (При согласовании с Федеральным правительством), занимающим должности с первой по восьмую порядковую, при выявлении нарушений статей, предусматривающих занесение в чёрный список и увольнение из организации. Неправомерное или неоправданное приостановление исполнения полномочий того или иного лица со стороны федерального бюро расследований можно обжаловать в судебном порядке.", category: "фп" },
    { id: 514, law: "Федеральное постановление", chapter: "Глава VII. Дополнительные положения", point: "7.2", text: "Сотрудник Генеральной прокуратуры имеет право осуществить занесение в Чёрный Список государственной организации (При согласовании с Федеральным правительством), занимающим должности с первой по восьмую порядковую, при выявлении нарушений статей, предусматривающих занесение в чёрный список и увольнение из организации. Неправомерное или неоправданное приостановление исполнения полномочий того или иного лица со стороны сотрудника Генеральной прокуратуры можно обжаловать в судебном порядке.", category: "фп" },
    { id: 515, law: "Федеральное постановление", chapter: "Глава VII. Дополнительные положения", point: "7.3", text: "Сотрудники СМИ, аккредитованные при МЮ/МО, имеют право беспрепятственного доступа на место проведения спецопераций (ЧС, похищения, облавы, рейды и т.п.) при предъявлении паспорта. Запрещается препятствовать присутствию журналиста на месте операции, если его действия не создают угрозы безопасности. Журналист обязан соблюдать указания куратора операции и не вмешиваться в действия спецподразделений. В случае нарушения порядка (создание помех, несанкционированная съемка стратегических объектов и т.д.) куратор спец. операции вправе ограничить доступ журналиста, но не может требовать его полного удаления без одобрения вышестоящего руководства. Необоснованное удаление журналиста с места операции влечет дисциплинарное взыскание для ответственного сотрудника МЮ/МО. Журналист, нарушивший правила поведения, может быть лишен аккредитации на подобные мероприятия.", category: "фп" },
    { id: 516, law: "Федеральное постановление", chapter: "Глава VII. Дополнительные положения", point: "7.4", text: "Нарушение Федерального Постановления штата Спэйс наказуемо. Любые нарушения, выявленные в рамках действия настоящего Федерального Постановления, подлежат наказанию в соответствии с законодательством штата Спэйс.", category: "фп" },
    { id: 517, law: "Федеральное постановление", chapter: "Глава VII. Дополнительные положения", point: "7.5", text: "Незнание Федерального Постановления штата Спэйс не освобождает от ответственности. Все лица, подпадающие под действие настоящего Федерального Постановления, обязаны быть в курсе его положений и соблюдать их, даже если они не знакомы со всеми его деталями.", category: "фп" },

    { id: 518, law: "Федеральное постановление", chapter: "Глава VIII. Вступление в силу", point: "8.1", text: "Федеральное Постановление вступает в силу с 28.09.2025. Все его положения и требования применяются с этой даты.", category: "фп" },

    // ============================================================
    // УГОЛОВНЫЙ КОДЕКС ШТАТА СПЭЙС — ОБЩАЯ ЧАСТЬ
    // ============================================================
    { id: 519, law: "Уголовный кодекс", chapter: "Глава I. Общие положения", point: "1", text: "Уголовный кодекс штата Спэйс — письменный нормативно-правовой акт, который определяет уголовно-противоправность деяния, а также его наказуемость и содержит в себе нормы, которые устанавливают основания, задачи и принципы уголовной ответственности, определяет, какие общественно опасные деяния являются преступлением и какие меры уголовной ответственности и другие меры уголовно-правового характера могут быть применены к лицам, которые их совершили.", category: "ук" },
    { id: 520, law: "Уголовный кодекс", chapter: "Глава I. Общие положения", point: "2", text: "Уголовный кодекс штата Спэйс состоит из Общей и Особенной части, которые содержат в себе нормы Общей и Особенной части Уголовного кодекса штата Спэйс. 1. В Общей части Уголовного кодекса штата Спэйс содержатся нормы, которые определяют задачи законодательства штата Спэйс об уголовной ответственности, основание уголовной ответственности, понятие, виды и порядок назначения наказания. 2. В Особенной части Уголовного кодекса штата Спэйс определяется круг общественно-опасных деяний, которые являются преступлениями, устанавливаются виды и размеры наказаний за совершение конкретных преступлений. 3. Большинство норм Особенной части Уголовного кодекса штата Спэйс являются однотипными по своей структуре и состоят из гипотезы, диспозиции и санкции статьи. Гипотеза определяет обстоятельства, при которых применяется норма уголовного права, в диспозиции определяются признаки преступления, за совершение которого установлена уголовная ответственность, а в санкции — вид и размер наказания, которое может быть назначено лицу, совершившему преступление. 4. Примечания, приложения к статьям Особенной части Уголовного кодекса штата Спэйс являются неотъемлемой частью закона и их необходимо учитывать при толковании и применении норм Особенной части Уголовного кодекса штата Спэйс. Примечания, приложения к статьям Особенной части Уголовного кодекса штата Спэйс являются частью текста закона и имеют юридическую силу наравне со статьями. 5. Рядом с номером статьи в Особенной части Уголовного кодекса штата Спэйс иногда проставляется символ “*”. Этот символ указывает на то, что наказание по данной статье может быть назначено исключительно по решению суда штата Спэйс.", category: "ук" },
    { id: 521, law: "Уголовный кодекс", chapter: "Глава I. Общие положения", point: "3", text: "Задачей Уголовного кодекса штата Спэйс является обеспечение законности и защита прав и свобод человека и гражданина штата Спэйс, собственности, общественного порядка и безопасности, конституционного строя штата Спэйс от преступных посягательств, обеспечение мира и безопасности человечества, а также предотвращение преступлений.", category: "ук" },

    { id: 522, law: "Уголовный кодекс", chapter: "Глава II. Основные принципы", point: "4", text: "Принцип законности. 1. Преступлением является лишь деяние, предусмотренное Уголовным кодексом штата Спэйс как преступление. 2. К лицу, совершившему противоправное деяние, предусмотренное Уголовным кодексом штата Спэйс, могут быть применены только определенные им уголовно-правовые последствия (санкции).", category: "ук" },
    { id: 523, law: "Уголовный кодекс", chapter: "Глава II. Основные принципы", point: "5", text: "Принцип равенства. 1. Все лица равны перед Уголовным кодексом штата Спэйс. 2. Не является нарушением принципа равенства установление Уголовным кодексом штата Спэйс особенностей уголовно-правовых последствий в отношении отдельных категорий лиц.", category: "ук" },
    { id: 524, law: "Уголовный кодекс", chapter: "Глава II. Основные принципы", point: "6", text: "Принцип пропорциональности. 1. Уголовно-правовые меры являются крайним средством реагирования штата Спэйс на противоправные деяния, предусмотренные Уголовным кодексом штата Спэйс. 2. Уголовно-правовые последствия устанавливаются в соответствии со степенью тяжести преступления и применяются с учетом степени тяжести совершенного преступления и личности виновного. 3. Чрезмерность уголовно-правовых последствий не допускается. Более строгое уголовно-правовое последствие устанавливается и применяется только тогда, когда менее строгое наказание недостаточно для достижения его цели.", category: "ук" },
    { id: 525, law: "Уголовный кодекс", chapter: "Глава II. Основные принципы", point: "7", text: "Принцип индивидуальности. 1. Уголовно-правовые меры, применяемые к лицу, имеют индивидуальный характер. Не допускается коллективная ответственность или ответственность лица за действия другого лица.", category: "ук" },
    { id: 526, law: "Уголовный кодекс", chapter: "Глава II. Основные принципы", point: "8", text: "Принцип однократности применения уголовно-правовых мер. 1. Лицо не может быть подвергнуто уголовно-правовым последствиям по Уголовному кодексу штата Спэйс более одного раза за одно и то же преступление. 2. Правонарушения совершённые до первоначального задержания и известные сотруднику на момент его оформления образуют совокупность в смысле статьи 24 настоящего Кодекса. После отбытия гражданином наказания за данную совокупность повторное задержание в целях привлечения к ответственности за правонарушения входившие в эту совокупность запрещается. 3. В случае если гражданин совершил несколько правонарушений до момента его задержания, то уполномоченный сотрудник обязан предъявить все выявленные нарушения в рамках одного задержания. Предъявление обвинений частично в нескольких задержаниях с целью обхода ограничений на совокупную и/или максимальную степень розыска, установленную статьёй 24 настоящего кодекса - не допускается. 4. Правонарушение не подлежит включению в совокупность и может быть предъявлено отдельно если оно совершено гражданином после первоначального задержания, либо не могло быть выявлено и предъявлено в рамках первоначального задержания по объективным причинам. В этом случае сотрудник вправе привлечь гражданина к ответственности в установленном законом порядке.", category: "ук" },
    { id: 527, law: "Уголовный кодекс", chapter: "Глава II. Основные принципы", point: "9", text: "Принцип вины. 1. Лицо подлежит уголовной ответственности только за те общественно опасные деяния и наступившие общественно опасные последствия, в отношении которых установлена его вина.", category: "ук" },

    { id: 528, law: "Уголовный кодекс", chapter: "Глава III. Законодательство штата Спэйс об уголовной ответственности", point: "10", text: "Законодательство штата Спэйс об уголовной ответственности. 1. Законодательство штата Спэйс об уголовной ответственности составляет Уголовный кодекс штата Спэйс, который основывается на Конституции штата Спэйс. 2. Противоправность деяния, а также его наказуемость и другие уголовно-правовые последствия определяются исключительно Уголовным кодексом штата Спэйс. 3. Если в другом кодексе или законе штата Спэйс уголовно-правовые отношения урегулированы иначе, чем Уголовным кодексом штата Спэйс, то применяются положения Уголовного кодекса штата Спэйс. 4. В случае противоречия между положениями Общей и Особенной части Уголовного кодекса штата Спэйс применяются положения Общей части Уголовного кодекса штата Спэйс.", category: "ук" },
    { id: 529, law: "Уголовный кодекс", chapter: "Глава III. Законодательство штата Спэйс об уголовной ответственности", point: "11", text: "Действие Уголовного кодекса штата Спэйс во времени. 1. Уголовный кодекс штата Спэйс вступает в силу в день, который указан в самом Уголовном кодексе штата Спэйс, но не ранее дня его опубликования. 2. Преступление и ответственность за него определяются нормами Уголовного кодекса штата Спэйс, которые действовали на момент совершения преступления. 3. Временем совершения преступления признается время совершения лицом предусмотренного Уголовным кодексом штата Спэйс действия или бездействия. 4. Уголовный кодекс штата Спэйс, отменяющий уголовную противоправность деяния, смягчающий уголовную ответственность или иным образом улучшающий положение лица, имеет обратную силу во времени, то есть распространяется на лиц, совершивших соответствующее деяние до вступления такого кодекса в силу, в том числе на лиц имеющих судимость.", category: "ук" },

    { id: 530, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "12", text: "Преступление — предусмотренное Уголовным кодексом штата Спэйс общественно опасное противоправное деяние (действие или бездействие), совершенное субъектом преступления.", category: "ук" },
    { id: 531, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "13", text: "Классификация преступлений. 1. Преступления делятся на нетяжкие, тяжкие и особо тяжкие: 1) не тяжкое преступление — предусмотренное Уголовным кодексом штата Спэйс деяние, за совершение которого предусмотрена выдача первой или второй степени розыска; 2) тяжкое преступление — предусмотренное Уголовным кодексом штата Спэйс деяние, за совершение которого предусмотрена выдача третьей или четвертой степени розыска; 3) особо тяжкое преступление — предусмотренное Уголовным кодексом штата Спэйс деяние, за совершение которого предусмотрена выдача пятой или шестой степени розыска.", category: "ук" },
    { id: 532, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "14", text: "Состав преступления — совокупность предусмотренных Уголовным кодексом штата Спэйс юридических признаков (объективных и субъективных), которые определяют общественно опасное деяние как преступление.", category: "ук" },
    { id: 533, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "15", text: "Элементы состава преступления — составляющие части преступления, которые объединяют в себе однородные юридические признаки, характеризующие преступления с определенной стороны. 1. Объект преступления — общественные отношения, которые находятся под охраной Уголовного кодекса штата Спэйс и которым вследствие совершения преступления причиняется существенный вред или создается угроза причинения такого вреда. То есть объектом преступления является то, чему причиняется вред при его совершении. 2. Объективная сторона преступления — внешняя его сторона, которая включает в себя общественно опасные деяния лица (действия или бездействия), общественно опасные последствия этого деяния, причинная связь между совершением преступления лицом деяния и его последствием, а также способ, обстановка, орудие, средства (предметы), место и время совершения преступления. 3. Субъект преступления — физическое лицо, которое совершило преступление. Этот элемент характеризует признак того, кто совершил преступление. 4. Субъективная сторона преступления — внутренняя его сторона, которая характеризует психологическое отношение лица к совершенному им деянию и его последствиям, а также характеризуется виной, мотивом и целями.", category: "ук" },
    { id: 534, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "16", text: "Деяние — конкретный, волевой, общественно опасный и противоправный акт поведения человека. Деяние может совершаться в форме действия или бездействия. 1. Действие — активный, волевой, общественно опасный, противоправный акт поведения человека. 2. Бездействие — пассивный, волевой, общественно опасный, противоправный акт поведения человеком, то есть не совершение лицом действий, которые он обязан (должен) был и мог совершить.", category: "ук" },
    { id: 535, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "17", text: "Малозначительное деяние — действие или бездействие, которое формально и содержит признаки какого-либо деяния, предусмотренного Уголовным кодексом штата Спэйс, но из-за малозначительности не представляет общественной опасности, то есть не причинило и не могло причинить существенного вреда физическому или юридическому лицу, обществу или штату Спэйс. Соответственно не является преступлением.", category: "ук" },
    { id: 536, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "18", text: "Общественно опасное последствие — негативные изменения, происходящие в объекте преступления или возникновение реальной угрозы причинения ему вреда вследствие совершения преступления.", category: "ук" },
    { id: 537, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "19", text: "Мотивом совершения преступления является осознанное внутреннее побуждение субъекта преступления к совершению деяния, предусмотренного Уголовным кодексом штата Спэйс.", category: "ук" },
    { id: 538, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "20", text: "Целью совершения преступления является представление субъекта преступления о желаемом последствии своего деяния, предусмотренного Уголовным кодексом штата Спэйс.", category: "ук" },
    { id: 539, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "21", text: "Значение мотива и цели. 1. В случае, когда они предусмотрены в диспозиции статьи Особенной части Уголовного кодекса штата Спэйс, или вытекают из его содержания, их установление является обязательным для констатации состава конкретного преступления. 2. В случае, когда мотив и цель не являются признаками состава конкретного преступления, они могут учитываться судом штата Спэйс как обстоятельства смягчающие, или отягчающие наказание. 3. Мотив и цель помогают в установлении формы вины, с которой совершено преступление.", category: "ук" },
    { id: 540, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "22", text: "Соучастие в преступлении — совместное участие нескольких субъектов преступления в совершении преступления.", category: "ук" },
    { id: 541, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "23", text: "Формы соучастия в преступлении — определенные объединения соучастников преступления, различающихся между собой по степени устойчивости субъективных связей между ними. 1. Формы соучастия в преступлении: 1) совершение преступления группой лиц имеет место, когда в нем принимают участие несколько (два или более) субъектов преступления без предварительного сговора между собой; 2) совершение преступления организованной группой характеризуется тем, что в его организации или совершении принимают участие несколько (три или более) субъектов преступления, которые предварительно организовались в устойчивое объединение для совершения этого и других преступлений; 3) совершение преступления преступной организацией (преступным сообществом) имеет место, если оно совершено устойчивым иерархическим объединением нескольких (пять и более) субъектов преступления, члены которого организовались для совместной деятельности с целью совершения этого и других преступлений.", category: "ук" },
    { id: 542, law: "Уголовный кодекс", chapter: "Глава IV. Преступление и его классификации", point: "24", text: "Совокупность преступлений — совершение лицом двух или более преступлений, предусмотренных разными статьями или разными частями одной статьи Особенной части Уголовного кодекса штата Спэйс, ни за одно из которых оно не было осуждено. Совокупность преступлений влияет на квалификацию преступления, потому что каждое из преступлений, которое образует совокупность, подлежит самостоятельной квалификации по соответствующей статье или части статьи Особенной части Уголовного кодекса штата Спэйс. При совокупности преступлений степень розыска не может превышать шести.", category: "ук" },

    { id: 543, law: "Уголовный кодекс", chapter: "Глава V. Вина и ее формы", point: "25", text: "Вина — психическое отношение лица к совершенному им и предусмотренному Уголовным кодексом штата Спэйс деянию и его последствиям, выраженное в форме умысла или неосторожности. 1. Формы вины: 1) умысел — форма вины, при которой лицо осознавало общественно опасный характер своего деяния, предполагало его общественно опасные последствия и желало (прямой умысел) или сознательно допускало (косвенный умысел) их наступление; 2) неосторожность — форма вины, при которой лицо предполагало возможность наступления общественно опасных последствий своего деяния, но легкомысленно рассчитывало на их предотвращение (уголовное противоправное легкомыслие) или не предполагало возможности наступления общественно опасных последствий своего деяния, хотя должно было и могло их предусмотреть (уголовная противоправная небрежность).", category: "ук" },
    { id: 544, law: "Уголовный кодекс", chapter: "Глава V. Вина и ее формы", point: "26", text: "Причинная связь — объективно существующая связь между деянием и его последствиями, когда совершенное лицом деяние в данных условиях с неизбежностью вызывает (порождает) наступление определенного общественно опасного последствия.", category: "ук" },
    { id: 545, law: "Уголовный кодекс", chapter: "Глава V. Вина и ее формы", point: "27", text: "Казус (случай) — невиновное причинение вреда, при котором лицо не предусматривало возможности общественно опасных последствий своего деяния, и не должно было и/или не могло их предусмотреть. Значение казуса заключается в том, что он исключает вину, как обязательный признак субъективной стороны преступления, а значит исключает и состав преступления. Привлечение к уголовной ответственности лица, психическое отношение к которому характеризуется казусом, исключается.", category: "ук" },

    { id: 546, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "28", text: "Наказание — мера принуждения, применяемая от имени штата Спэйс по приговору суда штата Спэйс к лицу, признанному виновным в совершении преступления, которая заключается в ограничении прав и свобод осужденного.", category: "ук" },
    { id: 547, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "29", text: "Цель наказания — цели, которых стремится достичь штат Спэйс, применяя определенный вид наказания к лицу, которое обвинительным приговором суда штата Спэйс признано виновным в совершении преступления. 1. К целям наказания относится: 1) кара — возмездие лицу за совершенное преступление. При назначении наказания в определенной степени обеспечивается чувства справедливости потерпевшего и общества, против которых совершено преступление; 2) исправление осужденного — влияние наказания на сознательность лица, совершившего преступление, с помощью которого устраняются те отрицательные черты осужденного, приведшие к совершению преступления; 3) превенция — предотвращение совершения новых преступлений со стороны осужденного и других лиц. Любой из предусмотренных в Уголовном кодексе штата Спэйс видов наказания должен обеспечивать достижение всех его целей. В тоже время не является целью наказания причинение осужденному физических страданий или унижения его человеческого достоинства, а потому никто не может быть подвергнут пыткам, жестокому, бесчеловечному или унижающему его достоинству обращению или наказанию.", category: "ук" },
    { id: 548, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "30", text: "Система наказания — совокупность взаимосвязанных и взаимодействующих между собой мер государственного принуждения, ограничивающих права и свободы лица, признанного виновным в совершении преступления. Эти меры имеют общие цели и назначаются по приговору суда штата Спэйс либо, в предусмотренных настоящим Кодексом случаях, по решению сотрудника Министерства юстиции штата Спэйс. Система наказания упорядочена в Уголовном кодексе штата Спэйс в зависимости от строгости и представляет собой обязательный для суда и сотрудников Министерства юстиции штата Спэйс исчерпывающий перечень отдельных видов наказания, расположенных от менее строгого к более строгому.", category: "ук" },
    { id: 549, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "31", text: "Виды наказаний. 1. К лицам, признанным виновными в совершении преступления, судом штата Спэйс могут быть применены следующие виды наказаний: 1) штраф; 2) увольнение с занимаемой должности; 3) лишение звания, ранга, чина или квалификационного класса; 4) лишение права занимать определенные должности или заниматься определенной деятельностью; 5) исправительные работы; 6) арест. 2. К лицам, задержанным сотрудниками Федерального Бюро Расследований штата Спэйс, могут быть применены следующие виды наказаний: 1) увольнение с занимаемой должности; 2) лишение права занимать определенные должности или заниматься определенной деятельностью; 3) арест. 3. К лицам, задержанным сотрудниками полицейских департаментов штата Спэйс, могут быть применены следующие виды наказаний: 1) арест.", category: "ук" },
    { id: 550, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "32", text: "Основные наказания — виды наказаний, которые всегда предусмотрены в санкциях статей Особенной части Уголовного кодекса штата Спэйс, назначаются только как самостоятельные меры принуждения, не могут присоединяться к другим видам наказаний и сочетаться между собой, при этом за одно преступление суд штата Спэйс вправе назначить только один вид основного наказания. 1. К основным видам наказаний относятся: 1) арест; 2) исправительные работы.", category: "ук" },
    { id: 551, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "33", text: "Дополнительные наказания — виды наказаний вспомогательного характера, не всегда предусмотренные в санкциях статей Особенной части Уголовного кодекса штата Спэйс, один или несколько из которых могут назначаться за одно преступление только путем их присоединения к основному наказанию и не могут быть назначены самостоятельно (без соединения с основным наказанием). 1. К дополнительным видам наказания относятся: 1) увольнение с занимаемой должности; 2) лишение звания, ранга, чина или квалификационного класса; 3) лишение права занимать определенные должности или заниматься определенной деятельностью.", category: "ук" },
    { id: 552, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "34", text: "Смешанный вид наказания — наказание, которое может назначаться либо как основное, либо как дополнительное. К смешанному виду наказания относится штраф.", category: "ук" },
    { id: 553, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "35", text: "Штраф — смешанный вид наказания, заключающийся в денежном взыскании, осуществляемом в пользу штата Спэйс и налагаемого как основное или дополнительное наказание в случаях и размере, установленных в санкциях статей Особенной части Уголовного кодекса штата Спэйс.", category: "ук" },
    { id: 554, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "36", text: "Увольнение с занимаемой должности — дополнительный вид наказания, заключающийся в принудительном прекращении трудовых отношений между работником и работодателем по решению суда штата Спэйс или сотрудника Федерального Бюро Расследований штата Спэйс.", category: "ук" },
    { id: 555, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "37", text: "Лишение звания, ранга, чина или квалификационного класса — дополнительный вид наказания, заключающийся в том, что лицо, имеющее звание, ранг, чин или квалификационный класс, осужденное за преступление, может быть лишено по приговору суда штата Спэйс этого звания, ранга, чина или квалификационного класса.", category: "ук" },
    { id: 556, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "38", text: "Лишение права занимать определенные должности или заниматься определенной деятельностью — дополнительный вид наказания, заключающийся во временном ограничении осужденного в праве занимать определенные должности или заниматься определенной служебной, профессиональной или иной деятельностью, которой он занимался и которая была связана с совершением им преступления, в течение срока, установленного решением суда штата Спэйс. 1. Лишение лицензий любого вида применимо только в тех случаях, когда это прямо предусмотрено статьей Особенной части Уголовного кодекса штата Спэйс или с целью предотвращения совершения новых подобных преступлений, совершённых с использованием или при помощи этих лицензий. 2. Лишение лицензий любого вида предоставляется суду штата Спейс, агентам Федерального Бюро Расследований, а также сотрудникам полицейских департаментов.", category: "ук" },
    { id: 557, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "39", text: "Исправительные работы — основной вид наказания, заключающийся в принудительном исполнении осужденным безвозмездных общественно полезных работ в свободное от работы время, вид и объем которых определяет суд штата Спэйс.", category: "ук" },
    { id: 558, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "40", text: "Арест — основной вид наказания, заключающийся в помещении и содержании осужденного в условиях изоляции от внешнего мира в течение определенного срока.", category: "ук" },
    { id: 559, law: "Уголовный кодекс", chapter: "Глава VI. Наказание и его виды", point: "41", text: "Специальная конфискация — принудительное безвозмездное изъятие из незаконного оборота боевых припасов (материалов), огнестрельного оружия, \"укроп\"тических веществ. Специальная конфискация не является видом наказания и применяется с целью пресечения текущего преступления и предотвращения совершения новых преступлений.", category: "ук" },

    { id: 560, law: "Уголовный кодекс", chapter: "Глава VII. Назначение наказания", point: "42", text: "Общие принципы назначения наказания — совокупность установленных законом и обязательных для суда штата Спэйс взаимосвязанных и взаимодействующих между собой исходных требований. Суд штата Спэйс должен исходить из этих требований при определении условий, оснований, порядка и пределов назначения наказания, а также при выборе конкретного вида и меры наказания для каждого отдельного преступления и каждого конкретного лица.", category: "ук" },
    { id: 561, law: "Уголовный кодекс", chapter: "Глава VII. Назначение наказания", point: "43", text: "Требования общих принципов назначения наказания: 1. Суд штата Спэйс назначает наказания в пределах, установленных санкцией статьи (части статьи) Особенной части Уголовного кодекса штата Спэйс, устанавливающей ответственность за совершенное преступление. 2. Суд штата Спэйс назначает наказания в соответствии с положениями Общей части Уголовного кодекса штата Спэйс: 1) суд штата Спэйс учитывает положения Общей части Уголовного кодекса штата Спэйс относительно целей наказаний, оснований, порядка, особенностей назначения отдельных его видов; 2) в случае возникновения коллизии между нормами Общей части и санкциями статей Особенной части Уголовного кодекса штата Спэйс предпочтение должно отдаваться именно предписаниям Общей части Уголовного кодекса штата Спэйс. 3. Суд штата Спэйс при назначении наказания обязательно учитывает: 1) степень тяжести совершенного преступления; 2) лицо виновного; 3) обстоятельства, смягчающие и отягчающие наказания.", category: "ук" },
    { id: 562, law: "Уголовный кодекс", chapter: "Глава VII. Назначение наказания", point: "44", text: "Обстоятельства, смягчающие наказание, как предусмотрены, так и не предусмотрены непосредственно в Уголовном кодексе штата Спэйс, но установлены судом штата Спэйс по конкретному делу как объективные и субъективные факторы, которые находятся вне состава преступления и не влияют на его квалификацию, но свидетельствуют о снижении степени общественной опасности совершенного деяния и/или лица виновного, и в связи с этим выступают основаниями для смягчения наказания, назначенного судом штата Спэйс.", category: "ук" },
    { id: 563, law: "Уголовный кодекс", chapter: "Глава VII. Назначение наказания", point: "45", text: "Обстоятельства, смягчающие наказание: 1. Искреннее раскаяние или активное содействие раскрытию преступления. 2. Добровольное возмещение причиненного ущерба. 3. Добровольное обращение (явка) лица в правоохранительные органы о совершенном им преступлении. 4. Оказание медицинской или иной помощи потерпевшему непосредственно после совершения преступления. 5. Совершение преступления с превышением пределов крайней необходимости. При назначении наказания суд штата Спэйс может признать и другие обстоятельства, которые смягчают наказание.", category: "ук" },
    { id: 564, law: "Уголовный кодекс", chapter: "Глава VII. Назначение наказания", point: "46", text: "Обстоятельства, отягчающие наказание, как предусмотрены, так и не предусмотрены непосредственно в Уголовном кодексе штата Спэйс, но установлены судом штата Спэйс по конкретному делу как объективные и субъективные факторы, которые находятся вне состава преступления и не влияют на его квалификацию, но свидетельствуют о повышении степени общественной опасности совершенного деяния и/или лица виновного, и в связи с этим выступают основаниями для усиления наказания, назначенного судом штата Спэйс.", category: "ук" },
    { id: 565, law: "Уголовный кодекс", chapter: "Глава VII. Назначение наказания", point: "47", text: "Обстоятельства, отягчающие наказание: 1. Совершение преступления с использованием служебных или должностных полномочий. 2. Совершение преступления в отношении лиц находящихся при исполнении служебных обязанностей. 3. Совершение преступления в соучастии. 4. Совершение преступления в условиях чрезвычайного или военного положения. 5. Рецидив преступлений. Если любое из перечисленных обстоятельств предусмотрено статьей или частью статьи Особенной части Уголовного кодекса штата Спэйс как квалифицирующий признак преступления, суд штата Спэйс не может повторно признавать его обстоятельством, отягчающим наказание.", category: "ук" },
    { id: 566, law: "Уголовный кодекс", chapter: "Глава VII. Назначение наказания", point: "48", text: "Специальные правила назначения наказания по совокупности преступлений применяются в случаях совершения лицом двух и более преступлений, предусмотренных разными статьями или разными частями одной статьи Особенной части Уголовного кодекса штата Спэйс, ни за одно из которых оно не было осуждено. 1. Назначение наказания в таких случаях происходит в два этапа: 1) Cуд штата Спэйс назначает основные и дополнительные наказания за каждое преступление, которое входит в совокупность, с учетом общих принципов назначения наказания; 2) Cуд штата Спэйс применяет принцип полного сложения наказаний, при котором все наказания, назначенные за отдельные преступления, суммируются, и окончательное наказание за совокупность преступлений составляет их общую сумму.", category: "ук" },

    { id: 567, law: "Уголовный кодекс", chapter: "Глава VIII. Обстоятельства, исключающие уголовную ответственность", point: "49", text: "Необходимая оборона — действия, совершенные с целью защиты охраняемых законом прав и интересов лица, защищающегося, а также общественных интересов и интересов штата Спэйс от общественно опасного посягательства путем причинения вреда лицу, совершившему посягательство, являются необходимой обороной, если такие действия были необходимы и достаточны в данной ситуации для немедленного отражения или прекращения посягательства, при этом не допущено превышения пределов необходимой обороны. 1. Каждое лицо имеет право на необходимую оборону независимо от возможности избежать общественно опасного посягательства или обратиться за помощью к другим лицам или органам власти. 2. Превышением пределов необходимой обороны признается умышленное причинение посягающему тяжкого вреда, который явно не соответствует опасности посягательства или обстановке защиты. 3. Значение необходимой обороны состоит в том, что она является обстоятельством, исключающим уголовную противоправность деяния, а следовательно, причинение вреда в состоянии необходимой обороны не может признаваться преступлением и не влечет за собой уголовной ответственности.", category: "ук" },
    { id: 568, law: "Уголовный кодекс", chapter: "Глава VIII. Обстоятельства, исключающие уголовную ответственность", point: "50", text: "Крайняя необходимость — вынужденное причинение вреда охраняемым законом интересам для устранения опасности, непосредственно угрожающей лицу или охраняемым законом правам этого лица или других лиц, а также общественным интересам или интересам штата Спэйс, если эту опасность в данной обстановке нельзя было устранить другими средствами и если при этом не было допущено превышения пределов крайней необходимости. 1. Причинение вреда в состоянии крайней необходимости преступлением не является и не влечет за собой уголовной ответственности.", category: "ук" },
    { id: 569, law: "Уголовный кодекс", chapter: "Глава VIII. Обстоятельства, исключающие уголовную ответственность", point: "51", text: "Превышение пределов крайней необходимости — умышленное причинение вреда охраняемым законом интересам, если такой ущерб является более значительным, чем предотвращенный. 1. Превышение пределов крайней необходимости влечет за собой уголовную ответственность за совершенное преступление, однако признается судом штата Спэйс обстоятельством смягчающим наказание.", category: "ук" },
    { id: 570, law: "Уголовный кодекс", chapter: "Глава VIII. Обстоятельства, исключающие уголовную ответственность", point: "52", text: "Исполнение законного приказа — обстоятельство, исключающее уголовную противоправность деяния за вред охраняемым законом интересам, причиненный с целью исполнения такого приказа. 1. Основания исполнения данного вида приказа: 1) законность приказа — приказ отдан соответствующим (уполномоченным) лицом, в должном порядке, в пределах полномочий такого лица, по содержанию не противоречит законодательству штата Спэйс, не связан с нарушением конституционных прав человека и гражданина штата Спэйс; 2) наличие у лица обязанности и реальной возможности исполнить отданный приказ. 2. Последствия исполнения законного приказа заключаются в том, что вред, причиненный с целью его исполнения, считается правомерным, а лицо, которое его причинило, не подлежит уголовной ответственности.", category: "ук" },
    { id: 571, law: "Уголовный кодекс", chapter: "Глава VIII. Обстоятельства, исключающие уголовную ответственность", point: "53", text: "Исполнение явно преступного приказа — действие или бездействие лица по исполнению приказа, которым предписывается совершить преступление. 1. Последствия исполнения преступного приказа: 1) лицо, которое отказалось исполнять явно преступный приказ, не подлежит уголовной ответственности; 2) если лицо осознавало явно преступный характер приказа и выполнило его, оно, как и лицо, отдавшее приказ, подлежит уголовной ответственности за умышленное причинение вреда на общих основаниях.", category: "ук" },
    { id: 572, law: "Уголовный кодекс", chapter: "Глава VIII. Обстоятельства, исключающие уголовную ответственность", point: "54", text: "Выполнение специального задания — вербовка сотрудников полицейских департаментов штата Спэйс в Федеральное Бюро Расследований штата Спэйс, участие в учебных и/или чрезвычайных ситуациях, внедрение и осуществление других задач, связанных с деятельностью Федерального Бюро Расследований штата Спэйс. 1. Не является уголовным правонарушением вынужденное причинение вреда охраняемым законом интересам лицом, которое в соответствии с законом выполняло специальное задание. 2. Лицо, указанное в части первой настоящей статьи, подлежит уголовной ответственности только за совершение особо тяжкого преступления, умышленного и соединенного с насилием над потерпевшим, а также при наступлении других тяжких или особо тяжких последствий. 3. Лицо, указанное в части второй настоящей статьи, не подлежит уголовной ответственности за совершение преступлений при выполнении приказов, находясь под прикрытием в нелегальных или преступных группировках, если избежать этих преступлений было невозможно или это поставило бы под угрозу выполнение специального задания.", category: "ук" },

    // ============================================================
    // УГОЛОВНЫЙ КОДЕКС — ОСОБЕННАЯ ЧАСТЬ
    // ============================================================
    { id: 573, law: "Уголовный кодекс", chapter: "Глава I. Преступления против здоровья, воли, чести и достоинства человека", point: "55.1", text: "Нападение, направленное на причинение вреда здоровью человека. Карается присвоением 3-ей степени розыска и арестом.", category: "ук" },
    { id: 574, law: "Уголовный кодекс", chapter: "Глава I. Преступления против здоровья, воли, чести и достоинства человека", point: "55.2", text: "Нападение, направленное на причинение вреда здоровью человека, которое привело к дальнейшей госпитализации лица. Карается присвоением 5-ой степени розыска и арестом.", category: "ук" },
    { id: 575, law: "Уголовный кодекс", chapter: "Глава I. Преступления против здоровья, воли, чести и достоинства человека", point: "56.1", text: "Похищение человека или лишение человека свободы передвижения в любой форме. Карается присвоением 5-ой степени розыска и арестом.", category: "ук" },
    { id: 576, law: "Уголовный кодекс", chapter: "Глава I. Преступления против здоровья, воли, чести и достоинства человека", point: "56.2", text: "Деяние, предусмотренное частью первой этой статьи, совершенное группой лиц или организованной группой, или преступной организацией, или такое, что сопровождалось причинением страданий и вреда здоровью похищенного. Карается присвоением 6-го степени розыска и арестом.", category: "ук" },
    { id: 577, law: "Уголовный кодекс", chapter: "Глава I. Преступления против здоровья, воли, чести и достоинства человека", point: "57.1", text: "Захват или удержание человека в качестве заложника с целью побуждения родственников захваченного, государственных и коммерческих организаций, предприятий, учреждений, физического или должностного лица к совершению или воздержанию от совершения любого действия как условия освобождения заложника. Карается присвоением 6-ой степени розыска и арестом.", category: "ук" },
    { id: 578, law: "Уголовный кодекс", chapter: "Глава I. Преступления против здоровья, воли, чести и достоинства человека", point: "58.1", text: "Халатное отношение государственного служащего к исполнению своих должностных обязанностей, выразившееся в ненадлежащем исполнении либо неисполнении возложенных на него обязанностей, повлекшее причинение вреда жизни или здоровью граждан, причинение имущественного ущерба, существенное нарушение их законных прав и интересов либо незаконное задержание или арест. Карается присвоением 6-ей степени розыска и арестом.", category: "ук" },

    { id: 579, law: "Уголовный кодекс", chapter: "Глава II. Преступления против неприкосновенности жилья, трудовых и других прав и свобод человека и гражданина", point: "59.1", text: "Незаконное проникновение в жилье или в другое владение лица. Карается сотрудником Министерства юстиции штата Спэйс присвоением 3-ой степени розыска и арестом. Карается судом штата Спэйс штрафом от $5,000,000 до $20,000,000 и/или исправительными работами, или присвоением 3-ой степени розыска и арестом.", category: "ук" },
    { id: 580, law: "Уголовный кодекс", chapter: "Глава II. Преступления против неприкосновенности жилья, трудовых и других прав и свобод человека и гражданина", point: "60.1", text: "Незаконное изъятие собранных журналистом материалов и технических средств, которыми он пользовался в связи со своей профессиональной деятельностью, незаконный запрет освещения отдельных тем, критики власти, а также любые другие умышленные препятствия осуществлению сотрудником средств массовой информации штата Спэйс своей профессиональной деятельности. Карается сотрудником Министерства юстиции штата Спэйс присвоением 2-ой степени розыска и арестом. Карается судом штата Спэйс штрафом от $5,000,000 до $25,000,000 и/или исправительными работами, или присвоением 2-ой степени розыска и арестом. Примечание 1. Запрещено осуществлять критику власти во время военного положения в штате.", category: "ук" },

    { id: 581, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "61.1", text: "Террористический акт, то есть применение оружия, совершение взрыва или иных действий, которые создали опасность для жизни или здоровья граждан штата Спэйс. Карается присвоением 6-ой степени розыска и арестом.", category: "ук" },
    { id: 582, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "61.2", text: "Публичные призывы к совершению террористического акта. Карается присвоением 3-ей степени розыска и арестом. Примечание 1. Под публичным призывом в настоящей статье подразумевается распространение призывов к неопределенному кругу лиц, в частности в местах массового скопления людей или с помощью средств массовой информации.", category: "ук" },
    { id: 583, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "62.1", text: "Участие (пребывание) в преступной группировке. Карается присвоением 6-ой степени розыска и арестом. Примечание 1. Под преступной группировкой в настоящей статье подразумевается объединение людей, участники которой занимаются преступной деятельностью. Группировка может быть признана преступной только на основании решения директора Федерального бюро расследований штата Спэйс, при условии предварительного составления федерального дела. Примечание 2. Само по себе ношение одежды, внешне характерной для участников преступных группировок, не является основанием для признания гражданина участником преступной группировки. Гражданин может быть подвергнут задержанию и обыску на основании статьи 26, пункта 2, подпункта 12 Процессуального кодекса. В случае обнаружения запрещённых предметов гражданин признаётся участником преступной группировки.", category: "ук" },
    { id: 584, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "63.1", text: "Заведомо ложное сообщение (вызов) о подготовке взрыва, поджога или других действий, угрожающих гибелью людей или другими тяжелыми последствиями. Карается сотрудником Министерства юстиции штата Спэйс присвоением 2-ой степени розыска и арестом. Карается судом штата Спэйс штрафом в $10,000,000 и/или исправительными работами, или присвоением 2-ой степени розыска и арестом.", category: "ук" },
    { id: 585, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "64.1", text: "Хищение (кража, воровство) оружия, боевых припасов, ингредиентов. Карается присвоением 4-ой степени розыска и арестом.", category: "ук" },
    { id: 586, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "65.1", text: "Хранение огнестрельного оружия, боевых припасов (материалов) без предусмотренного законом разрешения (лицензии). Карается сотрудником Министерства юстиции штата Спэйс присвоением 2-ой степени розыска и арестом. Карается судом штата Спэйс штрафом от $5,000,000 до $10,000,000 и/или исправительными работами, или присвоением 2-ой степени розыска и арестом.", category: "ук" },
    { id: 587, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "65.2", text: "Продажа или иная незаконная передача огнестрельного оружия, боевых припасов (материалов) не в предусмотренном для этого месте. Карается сотрудником Министерства юстиции штата Спэйс присвоением 2-ой степени розыска и арестом. Карается судом штата Спэйс штрафом от $5,000,000 до $10,000,000 и/или исправительными работами, или присвоением 2-ой степени розыска и арестом.", category: "ук" },
    { id: 588, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "65.3", text: "Не подлежит уголовной ответственности за совершение действий, предусмотренных частью первой настоящей статьи, лицо, добровольно сдавшее органам государственной власти оружие или боевые припасы (материалы).", category: "ук" },
    { id: 589, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "65.4", text: "Ношение огнестрельного оружия в открытом виде в многолюдных и общественных местах. Карается сотрудником Министерства юстиции штата Спэйс присвоением 3-ой степени розыска и арестом. Карается судом штата Спэйс штрафом от $5,000,000 до $10,000,000 или присвоением 3-ой степени розыска и арестом. Примечание 1. Под незаконным обращением с оружием в настоящей статье подразумевается ношение или хранение оружия без соответствующей лицензии. Примечание 2. Под предусмотренным местом в части второй настоящей статьи подразумеваются палатки в центре гетто. Примечание 3. Под органами государственной власти в части третьей настоящей статьи подразумеваются сотрудники Министерства юстиции штата Спэйс. Примечание 4. Гражданам штата разрешено обнажать и использовать огнестрельное оружие любого калибра для осуществления тренировочного процесса по увеличению навыков владения оружия исключительно внутри специализированных мест, при охоте и у себя дома. Примечание 5. Сотрудники правоохранительных органов обязаны дать одно предупреждение и потребовать убрать оружие в течении 10 секунд, после чего проверить у гражданина лицензию на оружие, если гражданин не ослушался, либо неоднократно достаёт оружие — то сотрудник правоохранительных органов имеет право задержать гражданина на месте и обвинить его в нарушении уголовного кодекса.", category: "ук" },
    { id: 590, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "66.1", text: "Лицо, которое приобрело или хранит, перевозит \"укроп\"тические вещества. Карается присвоением 3-ей степени розыска и арестом.", category: "ук" },
    { id: 591, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "66.2", text: "Лицо, которое продает или передает \"укроп\"тические вещества другим лицам. Карается присвоением 4-ой степени розыска и арестом.", category: "ук" },
    { id: 592, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "66.3", text: "Не подлежит уголовной ответственности за совершение действий, предусмотренных частью первой настоящей статьи, лицо, добровольно сдавшее органам государственной власти \"укроп\"тические вещества.", category: "ук" },
    { id: 593, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "66.4", text: "Сотрудникам проверяемой организации с момента уведомления о проведении проверки и до ее окончания запрещено сдавать \"укроп\"тические вещества, оружие и боевые припасы (материалы) органам государственной власти.", category: "ук" },
    { id: 594, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "66.5", text: "Агенты Федерального Бюро Расследований штата Спэйс не подлежат уголовной ответственности за хранение, перевозку или передачу \"укроп\"тических средств, изъятых из незаконного оборота, если это осуществляется в рамках их служебных обязанностей или других служебных действий, направленных на борьбу с незаконным оборотом \"укропа\". Агент Федерального Бюро Расследований обязан сдать все \"укроп\"тические вещества в течении 48 часов в камеру хранения вещественных доказательств. В случае нарушения этих правил агенты Федерального Бюро Расследований штата Спэйс могут быть привлечены к уголовной ответственности. Примечание 1. В настоящей статье \"укроп\"тическими веществами подразумеваются \"укроп\" (укроп), семена \"укропа\" (укропа), таблетки адреналина. Примечание 2. Под незаконным оборотом \"укроп\"тических веществ в настоящей статье подразумевается хранение или перевозка \"укропа\" более чем 20 единиц. Примечание 3. Под незаконным оборотом \"укроп\"тических веществ в настоящей статье подразумевается хранение или перевозка таблеток адреналина более чем 5 единиц. Примечание 4. В настоящей статье хранение, перевозка, продажа или передача семян \"укропа\" (укропа) запрещается в любом количестве. Примечание 5. Под органами государственной власти в части третьей настоящей статьи подразумеваются сотрудники Министерства юстиции штата Спэйс.", category: "ук" },
    { id: 595, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "67.1", text: "Лицо, которое садит, выращивает и/или собирает \"укроп\"тические вещества. Карается присвоением 4-ой степени розыска и арестом. Примечание 1. В настоящей статье \"укроп\"тическими веществами считаются \"укроп\" (укроп), семена \"укропа\" (укроп).", category: "ук" },
    { id: 596, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "68.1", text: "Публичное употребление \"укроп\"тических веществ в местах массового пребывания граждан штата Спэйс. Карается присвоением 2-ой степени розыска и арестом. Примечание 1. Под \"укроп\"тическими веществами в настоящей статье считаются \"укроп\" (укроп), таблетки адреналина. Примечание 2. Под местами массового пребывания граждан штата Спэйс в настоящей статье подразумеваются вокзалы, парки, пристани, рынки, спортивные площадки, улицы, площади и другие места, где пребывает два и более человека, или присутствует хотя бы один сотрудник Министерства юстиции штата Спэйс.", category: "ук" },
    { id: 597, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "69.1", text: "Ношение, хранение, перевозка отмычек от тюремных дверей. Карается присвоением 2-ой степени розыска и арестом.", category: "ук" },
    { id: 598, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "69.2", text: "Продажа или передача отмычек от тюремных дверей другим лицам. Карается присвоением 3-ей степени розыска и арестом.", category: "ук" },
    { id: 599, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "70.1", text: "Использование с целью получения материального вознаграждения или другой личной выгоды морского или наземного транспортного средства, применение насилия, ограбления или других враждебных действий в отношении водителя, пассажиров такого транспортного средства. Карается присвоением 5-ой степени розыска и арестом.", category: "ук" },
    { id: 600, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "70.2", text: "Любая форма незаконного проникновения в жилое помещение (дом, квартира, трейлер) с целью завладения чужим имуществом или другой личной выгоды. Карается присвоением 5-ой степени розыска и арестом.", category: "ук" },
    { id: 601, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "71.1", text: "Ношение оружия в открытом виде или использование оружия в условиях чрезвычайного или военного положения. Карается присвоением 4-ой степени розыска.", category: "ук" },
    { id: 602, law: "Уголовный кодекс", chapter: "Глава III. Преступления против общественной безопасности", point: "71.2", text: "Сотрудники Министерства юстиции, Министерства обороны штата Спэйс, которые находятся при исполнении своих должностных обязанностей, не подлежат уголовной ответственности за ношение оружия в открытом виде или использование оружия в условиях чрезвычайного или военного положения.", category: "ук" },

    { id: 603, law: "Уголовный кодекс", chapter: "Глава IV. Преступления против безопасности движения и эксплуатации транспорта", point: "72.1", text: "Незаконное завладение (угон) или попытка завладения транспортным средством. Карается присвоением 3-ой степени розыска и арестом.", category: "ук" },
    { id: 604, law: "Уголовный кодекс", chapter: "Глава IV. Преступления против безопасности движения и эксплуатации транспорта", point: "72.2", text: "Управление, использование, нахождение в транспортном средстве, которое заведомо находится в угоне. Карается присвоением 3-й степени розыска и арестом.", category: "ук" },
    { id: 605, law: "Уголовный кодекс", chapter: "Глава IV. Преступления против безопасности движения и эксплуатации транспорта", point: "72.3", text: "Освобождается от уголовной ответственности судом штата Спэйс лицо, которое совершило действие, предусмотренное частью первой настоящей статьи, и добровольно заявило об этом сотрудникам Министерства юстиции штата Спэйс, вернуло транспортное средство владельцу и полностью возместило причиненный ущерб.", category: "ук" },
    { id: 606, law: "Уголовный кодекс", chapter: "Глава IV. Преступления против безопасности движения и эксплуатации транспорта", point: "73.1", text: "Нарушение правил безопасности дорожного движения лицами, управляющими транспортными средствами, которые привели к причинению тяжкого вреда здоровью человека либо тяжкого вреда здоровью, повлекшего за собой со. Карается присвоением 3-ой степени розыска и арестом с лишением права управлять транспортным средством.", category: "ук" },
    { id: 607, law: "Уголовный кодекс", chapter: "Глава IV. Преступления против безопасности движения и эксплуатации транспорта", point: "73.2", text: "Нарушение правил безопасности дорожного движения лицами, управляющими транспортными средствами, которые привели к причинению тяжкого вреда здоровью сотрудника правоохранительных органов либо тяжкого вреда здоровью, повлекшего за собой дальнейшую госпитализацию. Карается присвоением 5-ой степени розыска и арестом с лишением права управлять транспортным средством.", category: "ук" },

    { id: 608, law: "Уголовный кодекс", chapter: "Глава V. Преступления против общественного порядка и моральности", point: "74.1", text: "Хулиганство, то есть грубое нарушение общественного порядка, выражающее явное неуважение к обществу, совершенное с применением насилия к гражданам либо угрозой его применения. Карается сотрудником Министерства юстиции штата Спэйс присвоением 2-ой степени розыска и арестом. Карается судом штата Спэйс штрафом от $5,000,000 до $7,500,000 и/или исправительными работами, или присвоением 2-ой степени розыска и арестом.", category: "ук" },
    { id: 609, law: "Уголовный кодекс", chapter: "Глава V. Преступления против общественного порядка и моральности", point: "74.2", text: "Телефонное хулиганство, то есть заведомо ложный вызов экстренных или специальных служб при отсутствии оснований либо по явно надуманной причине, а также систематические звонки с целью создания помех нормальной работе спец. служб. Карается сотрудником Министерства юстиции штата Спэйс присвоением 1-ой степени розыска и задержанием. Карается судом штата Спэйс штрафом от $2,500,000 до $5,000,000 и/или исправительными работами.", category: "ук" },
    { id: 610, law: "Уголовный кодекс", chapter: "Глава V. Преступления против общественного порядка и моральности", point: "75.1", text: "Проникновение на закрытую территорию. Карается сотрудником Министерства юстиции штата Спэйс присвоением 2-ой степени розыска и арестом. Карается судом штата Спэйс штрафом от $5,000,000 до $10,000,000 и/или исправительными работами, или присвоением 2-ой степени розыска и арестом. Примечание 1. Охраняемая (закрытая) территория — участок местности с расположенными на нем зданиями, сооружениями, площадками для хранения военной или другой техники, боевых припасов и имущества, транспортных средств, а также здания и сооружения, которые стоят отдельно, помещения в этих зданиях и сооружениях, которые ограждены и/или определены как охраняемые (закрытые) территории. Примечание 2. Режим допуска на охраняемые (закрытые) территории определяется внутренними регламентирующими документами.", category: "ук" },
    { id: 611, law: "Уголовный кодекс", chapter: "Глава V. Преступления против общественного порядка и моральности", point: "76.1", text: "Публичный призыв к поджогам, погромам, уничтожению имущества, захвату зданий или сооружений. Карается сотрудником Министерства юстиции штата Спэйс или присвоением 3-ей степени розыска и арестом. Карается судом штата Спэйс присвоением 3-ей степени розыска и арестом.", category: "ук" },
    { id: 612, law: "Уголовный кодекс", chapter: "Глава V. Преступления против общественного порядка и моральности", point: "76.2", text: "Участие в массовых беспорядках, поджогах, погромах, уничтожения имущества, захвату зданий или сооружений. Карается сотрудником Министерства юстиции штата Спэйс присвоением 4-ой степени розыска и арестом. Карается судом штата Спэйс присвоением 4-ой степени розыска и арестом. Примечание 1. Под публичным призывом в настоящей статье подразумевается распространение призывов к неопределенному кругу лиц, в частности в местах массового скопления людей или с помощью средств массовой информации.", category: "ук" },
    { id: 613, law: "Уголовный кодекс", chapter: "Глава V. Преступления против общественного порядка и моральности", point: "77.1", text: "Лицо, применившее оружие во время участия в массовых акциях или другом массовом мероприятии. Карается присвоением 3-ей степени розыска и арестом с лишением права на оружие или без такого.", category: "ук" },

    { id: 614, law: "Уголовный кодекс", chapter: "Глава VI. Преступления против правосудия", point: "78.1", text: "Сотрудник Министерства юстиции штата Спэйс, который без определенных законом оснований присвоил невиновному лицу степень розыска или арестовал его. Карается присвоением 3-ей степени розыска и арестом с лишением права занимать определенные должности или заниматься определенной деятельностью, или без такого.", category: "ук" },
    { id: 615, law: "Уголовный кодекс", chapter: "Глава VI. Преступления против правосудия", point: "79.1", text: "Свидетель, отказавшийся без уважительной причины дать показания в суде штата Спэйс, кроме отказа давать показания в отношении себя, членов своей семьи. Карается присвоением 2-ой степени розыска и арестом. Примечание 1. В настоящей статье членами семьи считаются супруг или супруга.", category: "ук" },
    { id: 616, law: "Уголовный кодекс", chapter: "Глава VI. Преступления против правосудия", point: "80.1", text: "Лицо, которое не исполнило принятое судом штата Спэйс судебное определение или препятствовало его исполнению (За исключением случаев отсутствия в штате посредством официального отгула (либо до 10 дней отсутствия в штате включительно)), карается судом штата Спэйс штрафом от $5,000,000 до $25,000,000, а также исправительными работами или присвоением 2-ой степени розыска и арестом.", category: "ук" },
    { id: 617, law: "Уголовный кодекс", chapter: "Глава VI. Преступления против правосудия", point: "80.2", text: "Лицо, которое не исполнило постановление Офиса Генерального Прокурора или препятствовало его исполнению (За исключением случаев отсутствия в штате посредством официального отгула (либо до 10 дней отсутствия в штате включительно)), признается виновным по настоящей статье, карается штрафом от $5,000,000 до $25,000,000, а также исправительными работами или присвоением 2-ой степени розыска и арестом. Примечание 1. В настоящей статье наказание за неисполнение или препятствие исполнению судебного решения не освобождает от обязанности исполнения судебного определения. Примечание 2. В настоящей статье наказание за неисполнение или препятствие исполнению постановления Офиса Генерального Прокурора не освобождает от обязанности исполнения такового постановления.", category: "ук" },
    { id: 618, law: "Уголовный кодекс", chapter: "Глава VI. Преступления против правосудия", point: "81.1", text: "Уклонение от уплаты штрафа или отказ от возмещения ущерба, или от наказания в виде лишения права занимать определенные должности или заниматься определенной деятельностью. Карается присвоением 3-ей степени розыска и арестом.", category: "ук" },
    { id: 619, law: "Уголовный кодекс", chapter: "Глава VI. Преступления против правосудия", point: "81.2", text: "Уклонение от отбывания наказания в виде исправительных работ. Карается присвоением 3-ей степени розыска и арестом.", category: "ук" },
    { id: 620, law: "Уголовный кодекс", chapter: "Глава VI. Преступления против правосудия", point: "82.1", text: "Умышленное сокрытие и/или уничтожение улик, имеющих значение для раскрытия преступления. Карается присвоением 3-ей степени розыска и арестом.", category: "ук" },
    { id: 621, law: "Уголовный кодекс", chapter: "Глава VI. Преступления против правосудия", point: "82.2", text: "Не подлежит уголовной ответственности за совершение действий, предусмотренных частью первой настоящей статьи, лицо, добровольно сообщившее правоохранительным органам штата Спэйс о факте сокрытия и/или уничтожения улик.", category: "ук" },
    { id: 622, law: "Уголовный кодекс", chapter: "Глава VI. Преступления против правосудия", point: "83.1", text: "Умышленное предоставление заведомо ложной информации, сокрытие фактов или введение в заблуждение в ходе официального расследования, допроса или судебного заседания. Карается присвоением 4-й степени розыска и арестом.", category: "ук" },
    { id: 623, law: "Уголовный кодекс", chapter: "Глава VI. Преступления против правосудия", point: "83.2", text: "Предъявление в суд штата Спэйс заведомо ложного иска, а равно умышленное включение в исковое заявление заведомо ложных сведений, имеющих существенное значение для дела. Карается присвоением 4-й степени розыска и арестом. Лицо, совершившее деяние, предусмотренное настоящей частью, освобождается от ответственности, если оно до вынесения судебного решения добровольно отозвало иск и письменно уведомило суд о его заведомой ложности. Примечание 1. Ошибка в показаниях, вызванная плохой памятью, стрессом или незнанием реальных фактов, не является составом преступления. Необходимо доказать умысел. Примечание 2. Лжесвидетельством признаются только сведения, имеющие существенное значение для дела, проверки или судебного разбирательства. Искажение несущественных деталей не образует состав преступления. Примечание 3. Лицо подлежит ответственности только в случае, если оно было надлежащим образом уведомлено о необходимости сообщать правдивые сведения и понимало последствия дачи ложной информации. Примечание 4. По части 2 настоящей статьи добросовестное заблуждение истца относительно фактов или ошибочная правовая оценка ситуации не образуют состава преступления.", category: "ук" },

    { id: 624, law: "Уголовный кодекс", chapter: "Глава VII. Преступления против конституционного строя штата Спэйс", point: "84.1", text: "Действия, совершенные с целью насильственного изменения или свержения конституционного строя или захвата государственной власти, а также заговор о совершении таких действий. Карается присвоением 6-ой степени розыска и арестом.", category: "ук" },
    { id: 625, law: "Уголовный кодекс", chapter: "Глава VII. Преступления против конституционного строя штата Спэйс", point: "85.1", text: "Умышленное разглашение сведений, составляющих государственную тайну, лицом, которому она была доверена или стала известна по службе, работе или учебе, при отсутствии признаков измены государству. Карается присвоением 6-ой степени розыска и арестом.", category: "ук" },
    { id: 626, law: "Уголовный кодекс", chapter: "Глава VII. Преступления против конституционного строя штата Спэйс", point: "85.2", text: "Незаконное получение, собирание, похищение, а равно хранение, передача, распространение или иное незаконное обращение со сведениями, составляющими государственную тайну, лицом, которому эти сведения не были доверены и не стали известны по службе, работе или учебе, при отсутствии признаков преступления, предусмотренного частью первой настоящей статьи. Карается присвоением 6-ой степени розыска и арестом. Примечание 1. Перечень сведений, относящихся к государственной тайне, виды секретности и порядок доступа к ним определяются Законом \"О государственной тайне\" штата Спэйс. Примечание 2. Не является разглашением государственной тайны передача сведений лицам, имеющим соответствующий допуск и действующим в рамках своих полномочий, а также в иных случаях, прямо предусмотренных законодательством штата Спэйс. Примечание 3. Лицо, добровольно сообщившее правоохранительным органам штата Спэйс о факте незаконного получения сведений, составляющих государственную тайну, и сдавшее все имеющиеся носители таких сведений, освобождается от уголовной ответственности по части второй настоящей статьи, если в его действиях не содержится иного состава преступления.", category: "ук" },

    { id: 627, law: "Уголовный кодекс", chapter: "Глава VIII. Преступления против органов государственной власти", point: "86.1", text: "Неподчинение, сопротивление сотруднику правоохранительных органов штата Спэйс при исполнении им служебных обязанностей. Карается сотрудником Министерства юстиции штата Спэйс присвоением 3-ей степени розыска и арестом. Карается судом штата Спэйс штрафом в $10,000,000 и/или исправительными работами, или присвоением 3-ей степени розыска и арестом.", category: "ук" },
    { id: 628, law: "Уголовный кодекс", chapter: "Глава VIII. Преступления против органов государственной власти", point: "86.2", text: "Нападение на сотрудника правоохранительных органов штата Спэйс. Карается присвоением 6-ой степени розыска и арестом. Примечание 1. Под неподчинением, сопротивлением сотруднику правоохранительных органов штата Спэйс в настоящей статье подразумевается злостное неповиновение, бездействие законному распоряжению или требованию сотрудника правоохранительных органов штата Спэйс. Примечание 2. Требование сотрудника правоохранительных органов о предъявлении документов, удостоверяющих личность, является законным при наличии предусмотренного законодательством основания для проверки документов. Сотрудник обязан сообщить гражданину причину проверки документов до предъявления соответствующего требования, за исключением случаев, когда такое сообщение невозможно, либо может воспрепятствовать проведению законного процессуального или оперативного мероприятия.", category: "ук" },
    { id: 629, law: "Уголовный кодекс", chapter: "Глава VIII. Преступления против органов государственной власти", point: "87.1", text: "Самовольное присвоение полномочий или звания должностного лица, связанное с использованием форменной одежды или служебного удостоверения сотрудника государственной организации, органа, учреждения. Карается присвоением 3-ей степени розыска и арестом. Примечание 1. Под самовольным присвоением полномочий или звания должностного лица в настоящей статье подразумевается неправомерное принятие лицом на себя полномочий представителя власти или звания должностного лица с введением в заблуждение окружающих относительно своего действительного статуса, совершенное в любой форме (словесной, представлением поддельных или чужих документов, использование форменной одежды и другие подобные действия). Примечание 2. В случае, если гражданин штата Спэйс не присваивал себе полномочий или звания должностного лица, однако использовал транспортное средство, внешне схожее с полицейским (например, личное авто с символикой или цветовой схемой, напоминающей полицейскую), или носил одежду, напоминающую форменную, такие действия не квалифицируются как самовольное присвоение полномочий или звания должностного лица, при отсутствии других вводящих в заблуждение действий, направленных на создание ложного представления о принадлежности к органам власти.", category: "ук" },
    { id: 630, law: "Уголовный кодекс", chapter: "Глава VIII. Преступления против органов государственной власти", point: "88.1", text: "Действия, направленные на воспрепятствование законной деятельности сотрудников государственной службы штата Спэйс при исполнении ими служебных обязанностей: караются присвоением 3-й степени розыска и арестом.", category: "ук" },
    { id: 631, law: "Уголовный кодекс", chapter: "Глава VIII. Преступления против органов государственной власти", point: "88.2", text: "Для целей настоящей статьи под сотрудниками государственной службы понимаются сотрудники: Министерства здравоохранения; Министерства юстиции; Министерства обороны; Центрального аппарата, включающий (Подразумевающий) Адвокатуру и Прокуратуру.", category: "ук" },
    { id: 632, law: "Уголовный кодекс", chapter: "Глава VIII. Преступления против органов государственной власти", point: "89.1", text: "Оскорбления/провокации по отношению к правоохранительным органам или судейской коллегии. Карается сотрудником Министерства юстиции штата Спэйс присвоением 2-ой степени розыска и арестом. Карается судом штата Спэйс штрафом от $5,000,000 до $10,000,000 или присвоением 2-ой степени розыска и арестом.", category: "ук" },

    { id: 633, law: "Уголовный кодекс", chapter: "Глава IX. Преступления в сфере служебной деятельности", point: "90.1", text: "Предложение или дача взятки должностному лицу. Карается присвоением 3-ей степени розыска и арестом.", category: "ук" },
    { id: 634, law: "Уголовный кодекс", chapter: "Глава IX. Преступления в сфере служебной деятельности", point: "91.1", text: "Принятие предложения или получение взятки должностным лицом. Карается сотрудником Министерства юстиции штата Спэйс присвоением 5-ой степени розыска и арестом. Карается судом штата Спэйс присвоением 5-ой степени розыска и арестом с лишением права занимать определенные должности или заниматься определенной деятельностью, или без такого.", category: "ук" },

    { id: 635, law: "Уголовный кодекс", chapter: "Глава X. Преступления против установленного порядка несения военной службы", point: "92.1", text: "Преступлениями против установленного порядка несения военной службы признаются предусмотренные настоящей главой преступления против установленного законодательством штата Спэйс несения или прохождения военной службы, совершенные военнослужащими штата Спэйс.", category: "ук" },
    { id: 636, law: "Уголовный кодекс", chapter: "Глава X. Преступления против установленного порядка несения военной службы", point: "92.2", text: "По соответствующим статьям настоящей главы несут ответственность военнослужащие штата Спэйс, а также другие лица, которые во время военного положения привлечены к непосредственному участию в военных действиях.", category: "ук" },
    { id: 637, law: "Уголовный кодекс", chapter: "Глава X. Преступления против установленного порядка несения военной службы", point: "92.3", text: "Лицо, совершившее преступление, предусмотренное статьями настоящей главы, может быть освобождено от уголовной ответственности с применением к нему мер, предусмотренных внутренними регламентирующими документами Министерства обороны штата Спэйс.", category: "ук" },
    { id: 638, law: "Уголовный кодекс", chapter: "Глава X. Преступления против установленного порядка несения военной службы", point: "93.1", text: "Самовольное оставление воинской части или места службы военнослужащим штата Спэйс с целью уклонения от военной службы, а также неявка с той же целью на службу, в том числе из отпуска или из лечебного учреждения. Карается сотрудником Министерства юстиции штата Спэйс присвоением 3-ей степени розыска и арестом. Карается судом штата Спэйс исправительными работами или присвоением 3-ей степени розыска и арестом с лишением права занимать определенные должности или заниматься определенной деятельностью, или без такого.", category: "ук" },
    { id: 639, law: "Уголовный кодекс", chapter: "Глава X. Преступления против установленного порядка несения военной службы", point: "94.1", text: "Похищение, присвоение военнослужащим штата Спэйс оружия, боевых припасов, транспортных средств или другого военного имущества с целью сбыта или передачи третьим лицам. Карается сотрудником Министерства юстиции штата Спэйс присвоением 5-ой степени розыска и арестом. Карается судом штата Спэйс присвоением 5-ой степени розыска и арестом с лишением права занимать определенные должности или заниматься определенной деятельностью, или без такого.", category: "ук" },

    { id: 640, law: "Уголовный кодекс", chapter: "Глава XI. Вступление в силу и изменения", point: "95", text: "Уголовный кодекс штата Спэйс вступает в силу с 17.11.2025. Все его положения и требования применяются с этой даты.", category: "ук" },
    { id: 641, law: "Уголовный кодекс", chapter: "Глава XI. Вступление в силу и изменения", point: "96", text: "Изменение Уголовного кодекса штата Спэйс возможно только в соответствии с Конституцией штата Спэйс.", category: "ук" },

    // ============================================================
    // АДМИНИСТРАТИВНЫЙ КОДЕКС ШТАТА СПЭЙС
    // ============================================================
    { id: 642, law: "Административный кодекс", chapter: "Глава I. Задача и цели", point: "1", text: "Задачами административного кодекса является охрана прав и свобод граждан, собственности, конституционного строя штата Спэйс, прав и законных интересов предприятий, учреждений и организаций, установления правопорядка, укрепление законности, предотвращение правонарушений, воспитание граждан в духе точного и неукоснительного соблюдения Конституции и законодательства штата Спэйс, уважения к правам, чести и достоинству других граждан, к правилам сосуществования, добросовестному исполнению своих обязанностей и ответственности перед обществом.", category: "ак" },
    { id: 643, law: "Административный кодекс", chapter: "Глава I. Задача и цели", point: "2", text: "Настоящий кодекс основывается на законодательстве штата Спэйс.", category: "ак" },
    { id: 644, law: "Административный кодекс", chapter: "Глава II. Основные принципы", point: "3", text: "Равенство - лица, совершившие административные правонарушения, равны перед законом. Физические лица подлежат административной ответственности независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также других обстоятельств.", category: "ак" },
    { id: 645, law: "Административный кодекс", chapter: "Глава II. Основные принципы", point: "4", text: "Малоимущие - лица, проживающие на территории штата Спэйс до 7 лет включительно, в отношении которых исключается административная ответственность.", category: "ак" },
    { id: 646, law: "Административный кодекс", chapter: "Глава II. Основные принципы", point: "5", text: "Законность - правоохранительные органы действуют в рамках законодательства штата Спэйс.", category: "ак" },
    { id: 647, law: "Административный кодекс", chapter: "Глава II. Основные принципы", point: "6", text: "Объективность - принятие административных решений основано на объективных фактах, доказательствах.", category: "ак" },
    { id: 648, law: "Административный кодекс", chapter: "Глава II. Основные принципы", point: "7", text: "Справедливость - решения принимаются на основе принципов справедливости, уважения прав и интересов граждан штата Спэйс.", category: "ак" },
    { id: 649, law: "Административный кодекс", chapter: "Глава II. Основные принципы", point: "8", text: "Презумпция невиновности - каждый обвиняемый в совершении преступления считается невиновным, до тех пор пока его виновность не будет доказана и установлена вступившим в законную силу постановлением суда штата Спэйс. 1. Обвинение не может основываться на незаконно полученных доказательствах, а также на предположениях. Все сомнения относительно доказанности вины обвиняемого толкуются в его пользу. 2. Никто не обязан доказывать свою невиновность в совершении преступления.", category: "ак" },
    { id: 650, law: "Административный кодекс", chapter: "Глава III. Административное правонарушение и административная ответственность", point: "9", text: "Каждый гражданин штата Спэйс несет ответственность за совершенные административные правонарушения, за исключением случаев, предусмотренных статьей 4 настоящего закона.", category: "ак" },
    { id: 651, law: "Административный кодекс", chapter: "Глава III. Административное правонарушение и административная ответственность", point: "10", text: "Административным правонарушением признается противоправное, действие или бездействие физического лица, за которое настоящим административным кодексом установлена административная ответственность.", category: "ак" },
    { id: 652, law: "Административный кодекс", chapter: "Глава III. Административное правонарушение и административная ответственность", point: "11", text: "Административное правонарушение признается совершенным умышленно, если лицо, его совершившее, осознавало противоправный характер своего действия или бездействия, предвидело его вредные последствия и желало наступления таких последствий или сознательно их допускало либо относилось к ним безразлично.", category: "ак" },
    { id: 653, law: "Административный кодекс", chapter: "Глава III. Административное правонарушение и административная ответственность", point: "12", text: "Административное правонарушение признается совершенным по неосторожности, если лицо, его совершившее, предвидело возможность наступления вредных последствий своего действия или бездействия, но без достаточных к тому оснований самонадеянно рассчитывало на предотвращение таких последствий либо не предвидело возможности наступления таких последствий, хотя должно было и могло их предвидеть.", category: "ак" },
    { id: 654, law: "Административный кодекс", chapter: "Глава III. Административное правонарушение и административная ответственность", point: "13", text: "Административной ответственности подлежит должностное лицо в случае совершения им административного правонарушения в связи с неисполнением либо ненадлежащим исполнением своих служебных обязанностей.", category: "ак" },
    { id: 655, law: "Административный кодекс", chapter: "Глава III. Административное правонарушение и административная ответственность", point: "14", text: "Административной ответственности не подлежит лицо, обладающее неприкосновенностью.", category: "ак" },
    { id: 656, law: "Административный кодекс", chapter: "Глава III. Административное правонарушение и административная ответственность", point: "15", text: "Сотрудники полицейских департаментов, федерального бюро расследований, S.W.A.T., медицинских центров, пожарной безопасности, военнослужащие административную ответственность по настоящему Кодексу не несут при условии того, что правонарушение было совершено во время исполнения рабочих обязанностей.", category: "ак" },
    { id: 657, law: "Административный кодекс", chapter: "Глава III. Административное правонарушение и административная ответственность", point: "16", text: "При малозначительности совершенного административного правонарушения управомоченное лицо может освободить лицо, совершившее административное правонарушение, от административной ответственности и ограничиться предупреждением.", category: "ак" },
    { id: 658, law: "Административный кодекс", chapter: "Глава III. Административное правонарушение и административная ответственность", point: "17", text: "Лицо освобождается от административной ответственности, если со дня совершения правонарушения прошло 7 дней, при этом лицо намеренно не скрывалось от ответственности.", category: "ак" },
    { id: 659, law: "Административный кодекс", chapter: "Глава IV. Административное наказание", point: "18", text: "Виды административных наказаний: 1) Предупреждение; 2) Штраф; 3) Исправительные работы; 4) Изъятие лицензии на вождение.", category: "ак" },
    { id: 660, law: "Административный кодекс", chapter: "Глава IV. Административное наказание", point: "19", text: "Каждое лицо, совершившее административное правонарушение, должно понести заслуженное наказание, предусмотренное законодательством штата Спэйс, за исключением случаев, предусмотренных статьей 4 настоящего закона, а также в главе 3 настоящего закона.", category: "ак" },
    { id: 661, law: "Административный кодекс", chapter: "Глава IV. Административное наказание", point: "20", text: "В случае неправомерно выписанного наказания сотрудник или судья, выписавший его, будет нести ответственность в соотношении с законодательством штата Спэйс.", category: "ак" },
    { id: 662, law: "Административный кодекс", chapter: "Глава IV. Административное наказание", point: "21", text: "Сотрудники правоохранительных органов штата Спэйс имеют право воспользоваться при вынесении наказания только предупреждением и штрафом. К исправительным работам может привлекать только судейская коллегия.", category: "ак" },
    { id: 663, law: "Административный кодекс", chapter: "Глава IV. Административное наказание", point: "22", text: "Предупреждение - мера административного наказания, выраженная в официальном порицании физического лица. Предупреждение выносится в устной форме.", category: "ак" },
    { id: 664, law: "Административный кодекс", chapter: "Глава IV. Административное наказание", point: "23", text: "Штраф - денежное взыскание, устанавливается данным административным кодексом.", category: "ак" },
    { id: 665, law: "Административный кодекс", chapter: "Глава IV. Административное наказание", point: "24", text: "Исправительные работы (перенос сена, работа на заводе и иные работы, которые может установить судейская коллегия) заключаются в выполнении физическим лицом, совершившим административное правонарушение, в свободное от основной работы, службы или учебы время бесплатных общественно полезных работ. Исправительные работы назначаются судьей.", category: "ак" },
    { id: 666, law: "Административный кодекс", chapter: "Глава V. Привлечение к административной ответственности", point: "25", text: "Привлечение к административной ответственности возможно только сотрудниками полицейских департаментов, сотрудниками SWAT и Федерального бюро расследований в случаях, предусмотренных законом «О деятельности государственных структур Штата Спэйс», а также судом штата Спэйс.", category: "ак" },
    { id: 667, law: "Административный кодекс", chapter: "Глава VI. Управление транспортным средством в нетрезвом виде", point: "26", text: "За управление транспортным средством в состоянии алкогольного опьянения предусматривается штраф в размере $300,000.", category: "ак" },
    { id: 668, law: "Административный кодекс", chapter: "Глава VI. Управление транспортным средством в нетрезвом виде", point: "27", text: "За управление транспортным средством под воздействием \"укроп\"тических, психотропных или токсических веществ предусматривается штраф в размере $300,000. Не относится к лекарственным препаратам, выписанным по рецепту лечащего врача.", category: "ак" },
    { id: 669, law: "Административный кодекс", chapter: "Глава VII. Использование мобильных телефонов за рулем", point: "28", text: "За использование мобильных устройств за рулем, во время вождения транспортного средства предусматривается штраф в размере $150,000.", category: "ак" },
    { id: 670, law: "Административный кодекс", chapter: "Глава VIII. Езда на транспортном средстве", point: "29", text: "За использование неисправного транспортного средства предусматривается штраф в размере $150,000.", category: "ак" },
    { id: 671, law: "Административный кодекс", chapter: "Глава VIII. Езда на транспортном средстве", point: "30", text: "За вождение без регистрационных номеров предусматривается штраф в размере $300,000.", category: "ак" },
    { id: 672, law: "Административный кодекс", chapter: "Глава VIII. Езда на транспортном средстве", point: "31", text: "За движение транспортного средства по полосе встречного движения предусматривается штраф в размере $700,000.", category: "ак" },
    { id: 673, law: "Административный кодекс", chapter: "Глава IX. Парковка и движение транспортного средства в неположенном месте", point: "32", text: "За парковку в неположенном месте предусматривается штраф в размере $450,000.", category: "ак" },
    { id: 674, law: "Административный кодекс", chapter: "Глава IX. Парковка и движение транспортного средства в неположенном месте", point: "33", text: "За движение по тротуарам, велосипедным и пешеходным дорожкам предусматривается штраф в размере $540,000.", category: "ак" },
    { id: 675, law: "Административный кодекс", chapter: "Глава IX. Парковка и движение транспортного средства в неположенном месте", point: "34", text: "За движение по обочине нарушитель предусматривается штраф в размере $360,000.", category: "ак" },
    { id: 676, law: "Административный кодекс", chapter: "Глава IX. Парковка и движение транспортного средства в неположенном месте", point: "35", text: "За брошенный транспорт на дороге, сотрудник правоохранительных органов штата Спэйс имеет право эвакуировать транспорт и выписать штраф в размере $290,000.", category: "ак" },
    { id: 677, law: "Административный кодекс", chapter: "Глава IX. Парковка и движение транспортного средства в неположенном месте", point: "36", text: "За движение по газонам или песку нарушитель предусматривается штраф в размере $360,000.", category: "ак" },
    { id: 678, law: "Административный кодекс", chapter: "Глава IX. Парковка и движение транспортного средства в неположенном месте", point: "37", text: "За езду по железнодорожным путям нарушитель предусматривается штраф в размере $550,000.", category: "ак" },
    { id: 679, law: "Административный кодекс", chapter: "Глава X. Затруднение движения", point: "38", text: "За затруднение движения на проезжих частях предусматривается штраф в размере $300,000.", category: "ак" },
    { id: 680, law: "Административный кодекс", chapter: "Глава X. Затруднение движения", point: "39", text: "За затруднение движения на проезжих частях, вследствие чего произошло дорожно-транспортное происшествие предусматривается штраф в размере $1,000,000, а также моральный ущерб пострадавшему.", category: "ак" },
    { id: 681, law: "Административный кодекс", chapter: "Глава XI. Дорожно-транспортное происшествие", point: "40", text: "В случае достижения морального и материального соглашения между участниками дорожно-транспортного происшествия, дорожно-транспортное происшествие признается недействительным, и обращение к сотруднику правоохранительных органов штата Спэйс не требуется.", category: "ак" },
    { id: 682, law: "Административный кодекс", chapter: "Глава XI. Дорожно-транспортное происшествие", point: "41", text: "При наличии пострадавших в результате дорожно-транспортного происшествия, виновник подвергается уголовной ответственности согласно уголовному кодексу штата Спэйс.", category: "ак" },
    { id: 683, law: "Административный кодекс", chapter: "Глава XI. Дорожно-транспортное происшествие", point: "42", text: "За причинение вреда пешеходу в результате дорожно-транспортного происшествия, нарушитель обязан компенсировать моральный ущерб пострадавшему, который оценивается сотрудником правоохранительных органов.", category: "ак" },
    { id: 684, law: "Административный кодекс", chapter: "Глава XI. Дорожно-транспортное происшествие", point: "43", text: "За покидание места дорожно-транспортного происшествия или попытку покинуть его предусматривается штраф в размере $1,000,000.", category: "ак" },
    { id: 685, law: "Административный кодекс", chapter: "Глава XII. Пешеходы", point: "44", text: "За переход дороги в неположенном месте, либо же за передвижение пешехода по проезжей части дороги пешеходом предусматривается штраф в размере $110,000.", category: "ак" },
    { id: 686, law: "Административный кодекс", chapter: "Глава XII. Пешеходы", point: "45", text: "За создание аварийной ситуации пешеходом предусматривается штраф в размере $250,000.", category: "ак" },
    { id: 687, law: "Административный кодекс", chapter: "Глава XIII. Использование городского транспорта в личных целях", point: "46", text: "За использование городского транспорта в личных целях предусматривается штраф в размере $300,000.", category: "ак" },
    { id: 688, law: "Административный кодекс", chapter: "Глава XIV. Нарушение общественного порядка", point: "47", text: "За распитие алкогольных напитков в общественных местах предусматривается штраф в размере 150,000$.", category: "ак" },
    { id: 689, law: "Административный кодекс", chapter: "Глава XIV. Нарушение общественного порядка", point: "48", text: "За неадекватное поведение в публичных местах, такое как публичное раздевание, залезание на остановки и другие подобные действия, а также проявление неадекватных высказываний и криков предусматривается штраф в размере $200,000.", category: "ак" },
    { id: 690, law: "Административный кодекс", chapter: "Глава XIV. Нарушение общественного порядка", point: "49", text: "За беспричинное использование огнетушителей, баллончиков с краской и прочих пачкающих веществ вблизи людей и муниципальных объектов предусматривается штраф в размере $150,000.", category: "ак" },
    { id: 691, law: "Административный кодекс", chapter: "Глава XIV. Нарушение общественного порядка", point: "50", text: "Публичное громкое прослушивание музыки, если имеются жалобы со стороны других лиц предусматривается в размере $110,000.", category: "ак" },
    { id: 692, law: "Административный кодекс", chapter: "Глава XIV. Нарушение общественного порядка", point: "51", text: "За использование нецензурной лексики в общественных местах предусматривается штраф в размере $150,000.", category: "ак" },
    { id: 693, law: "Административный кодекс", chapter: "Глава XIV. Нарушение общественного порядка", point: "52", text: "За участие в уличных гонках или организацию таких гонок предусматривается штраф в размере $300,000.", category: "ак" },
    { id: 694, law: "Административный кодекс", chapter: "Глава XIV. Нарушение общественного порядка", point: "53", text: "За действия и/или слова, оскорбляющие честь и достоинство гражданина, предусматривается штраф в размере $1,000,000.", category: "ак" },
    { id: 695, law: "Административный кодекс", chapter: "Глава XIV. Нарушение общественного порядка", point: "54", text: "За ношение маски гражданскому лицу в общественном месте, предусматривается штраф в размере $1,000,000.", category: "ак" },
    { id: 696, law: "Административный кодекс", chapter: "Глава XV. Порча имущества", point: "55", text: "За нанесение ущерба имуществу граждан штата Спэйс, государственных организаций и частных лиц предусматривается штраф в размере $200,000.", category: "ак" },
    { id: 697, law: "Административный кодекс", chapter: "Глава XVI. Вступление в силу и изменения", point: "56", text: "Настоящий Кодекс вступает в силу с 17.11.2025. Все его положения и требования применяются с этой даты.", category: "ак" },

    // ============================================================
    // УСТАВ ВОЕННОЙ ПОЛИЦИИ
    // ============================================================
    { id: 698, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.1", text: "Устав Военной Полиции - это внутриорганизационный документ, регламентирующий деятельность сотрудников.", category: "устав ВП" },
    { id: 699, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.2", text: "Командование Военной Полицией осуществляется Куратором Военной Полиции при помощи Заместителей Куратора Военной Полиции.", category: "устав ВП" },
    { id: 700, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.3", text: "В состав Военной Полиции входит 10 сотрудников военной полиции, 1 Куратор ВП, 2 Зама Куратора ВП.", category: "устав ВП" },
    { id: 701, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.3.1", text: "Заместители Куратора ВП назначаются решением Куратора ВП из числа наиболее подготовленных сотрудников Военной Полиции.", category: "устав ВП" },
    { id: 702, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.4", text: "Устав может быть отредактирован в любой момент по решению сената.", category: "устав ВП" },
    { id: 703, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.5", text: "Устав является действительным только с момента публикации на официальном портале штата.", category: "устав ВП" },
    { id: 704, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.6", text: "За нарушение какого-либо пункта данного нормативного акта, руководство организации имеет право на дисциплинарное взыскание в виде выговора, понижения или увольнения.", category: "устав ВП" },
    { id: 705, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.7", text: "При грубых или многократных нарушениях устава военной полиции, человек может быть подвержен наказанием вплоть до Чёрного Списка Министерства Обороны с возможностью выхода.", category: "устав ВП" },
    { id: 706, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.8", text: "Сотрудники Военной Полиции подчиняются Министру Обороны, Руководству ТСР, Куратору/Заместителям Куратора Военной Полиции и первым лицам штата.", category: "устав ВП" },
    { id: 707, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.8.1", text: "Руководству ТСР запрещается отдавать указания, приказы или распоряжения, содержащие формулировки по типу запрещаю трогать сотрудников ТСР, а также иным образом препятствовать законной деятельности сотрудников Военной Полиции в отношении сотрудников ТСР, если действия ВП осуществляются в рамках устава, законодательства штата и служебных обязанностей.", category: "устав ВП" },
    { id: 708, law: "Устав Военной Полиции", chapter: "Глава 1. Общие положения", point: "1.9", text: "При увольнении/уходе сотрудника военной полиции со своей должности, он заноситься в черный список Министерства Обороны только в том случае, если не прошел испытательный срок.", category: "устав ВП" },
    { id: 709, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.1", text: "Обязаны знать и соблюдать Конституцию, ФП, УК, АК, Устав Военной полиции.", category: "устав ВП" },
    { id: 710, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.1.1", text: "Обязаны знать и соблюдать устав МО.", category: "устав ВП" },
    { id: 711, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.1.2", text: "Сотрудники Военной Полиции обязаны знать и соблюдать положения Системы взводов Министерства Обороны, относящиеся к деятельности Военной Полиции.", category: "устав ВП" },
    { id: 712, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.2", text: "Выполнять свои должностные обязанности качественно.", category: "устав ВП" },
    { id: 713, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.3", text: "Подходить к задаче поставленной руководством ответственно.", category: "устав ВП" },
    { id: 714, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.4", text: "Выполнять законные требования руководства.", category: "устав ВП" },
    { id: 715, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.5", text: "По возможности быть подключенным к специальной рации во время выполнения своих должностных обязанностей. Примечание: пункт является не обязательным.", category: "устав ВП" },
    { id: 716, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.6", text: "Разговаривать со всеми уважительно в деловом тоне.", category: "устав ВП" },
    { id: 717, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.6.1", text: "Соблюдать субординацию во время общения с Куратором Военной Полиции, старшими офицерами ВП и руководством соответствующей организации.", category: "устав ВП" },
    { id: 718, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.7", text: "Сотрудник, не появившийся на службе в течение 7 календарных дней без уведомления старшего состава, подлежит увольнению, за исключением случаев нахождения в отпуске либо при наличии уважительных причин.", category: "устав ВП" },
    { id: 719, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.8", text: "При запросе военнослужащего у сотрудника Военной Полиции удостоверения или паспорта для подтверждения личности, сотрудник обязан показать его.", category: "устав ВП" },
    { id: 720, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.9", text: "Стажёр Военной Полиции обязан пройти установленную подготовку и сдать экзамен в течение 7 календарных дней. В случае несдачи экзамена в установленный срок стажировка прекращается, а сотрудник продолжает службу в своём основном взводе ТСР.", category: "устав ВП" },
    { id: 721, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10", text: "Каждый сотрудник/военнослужащий обязан по первому требованию предоставить свои документы сотруднику Военной полиции только в случаях, предусмотренных настоящим регламентом, при условии, что сотрудник Военной полиции действует в рамках исполнения служебных обязанностей.", category: "устав ВП" },
    { id: 722, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.1", text: "Сотрудник ТСР или военнослужащий Министерства Обороны обязан предъявить документы сотруднику Военной полиции, если требование связано с: проводится проверка соблюдения порядка и дисциплины; проводится проверка или расследование нарушения; проводится проверка при въезде или выезде с территории; проверяется право нахождения на территории воинской части или другого охраняемого объекта; проводится служебная проверка; на человека имеется ориентировка или есть основания считать, что он нарушил правила; необходимо установить личность человека, который участвовал в происшествии или был его свидетелем.", category: "устав ВП" },
    { id: 723, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.2", text: "Перед требованием документов сотрудник Военной полиции обязан: представиться; сообщить своё звание и должность; Предъявить служебное удостоверение в установленном порядке; кратко разъяснить основание и цель проверки документов.", category: "устав ВП" },
    { id: 724, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.3", text: "Требование о предъявлении документов должно быть непосредственно связано с исполнением служебных обязанностей сотрудника Военной полиции. Запрещается требовать документы без служебной необходимости, исключительно из личной заинтересованности либо с целью необоснованного ограничения прав военнослужащего или сотрудника.", category: "устав ВП" },
    { id: 725, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.4", text: "Военнослужащий или сотрудник ТСР имеет право отказаться от предъявления документов, если: сотрудник Военной полиции не представился и не сообщил своё звание и должность; сотрудник Военной полиции не разъяснил основание и цель проверки; требование документов не связано с исполнением служебных обязанностей; сотрудник Военной полиции находится вне исполнения служебных обязанностей; сотрудник Военной полиции ведёт себя неподобающим образом: допускает угрозы, грубость, оскорбления или иные нарушения служебной этики; сотрудник Военной полиции требует документы в месте или обстоятельствах, не предусмотренных настоящим регламентом, за исключением случаев проведения специальных мероприятий или возникновения чрезвычайной ситуации.", category: "устав ВП" },
    { id: 726, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.5", text: "На территории воинской части сотрудник Военной полиции вправе осуществлять проверку документов лиц, находящихся на территории объекта, в целях установления личности, проверки права нахождения на территории и соблюдения установленного пропускного режима. Исключение: Если сотрудник находиться на территории своей Военной базы. У сотрудника Военной Полиции должно быть веское основание чтобы провести проверку.", category: "устав ВП" },
    { id: 727, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.6", text: "Вне территории воинской части требование документов допускается только при наличии конкретного служебного основания, предусмотренного пунктом 2.15.1 настоящего регламента.", category: "устав ВП" },
    { id: 728, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.7", text: "При проведении массовых мероприятий, специальных операций, усиленного режима или иных мероприятий, официально объявленных руководством, сотрудник Военной полиции вправе осуществлять проверку документов в пределах задач и территории проводимого мероприятия.", category: "устав ВП" },
    { id: 729, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.8", text: "Проверка документов не должна длиться дольше, чем это необходимо для установления личности и проверки соответствующих обстоятельств.", category: "устав ВП" },
    { id: 730, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.9", text: "После установления личности и отсутствия оснований для дальнейшей проверки сотрудник Военной полиции обязан прекратить проверку и вернуть предъявленные документы владельцу.", category: "устав ВП" },
    { id: 731, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.10", text: "Сотрудник Военной полиции не вправе изымать документы у военнослужащего или сотрудника ТСР без предусмотренного законом, приказом или иным внутренним нормативным актом основания.", category: "устав ВП" },
    { id: 732, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.11", text: "При возникновении спорной ситуации военнослужащий или сотрудник ТСР вправе запросить у сотрудника Военной полиции разъяснение основания проверки и обратиться к непосредственному руководителю либо в установленный порядок обжалования действий сотрудника Военной полиции.", category: "устав ВП" },
    { id: 733, law: "Устав Военной Полиции", chapter: "Глава 2. Обязанности сотрудников", point: "2.10.12", text: "Нарушение сотрудником Военной полиции установленного порядка требования и проверки документов является основанием для проведения служебной проверки и привлечения виновного лица к ответственности в соответствии с действующими внутренними нормативными актами.", category: "устав ВП" },
    { id: 734, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.1", text: "Сотрудники военной полиции имеют право свободного нахождения на территории воинской части с разрешением офицерского состава (5+ ранг) той армии, в чью воинскую часть они заезжают.", category: "устав ВП" },
    { id: 735, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.1.1", text: "Сотрудники военной полиции находясь на воинской части армии обязаны при себе иметь: Удостоверение сотрудника ВП, Балаклава, Бронежилет, Орудие(М4, Дигл, оглашающий пистолет или дубинка) и Боди-камера.", category: "устав ВП" },
    { id: 736, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.1.2", text: "В случае отсутствия ответа от офицерского состава сотрудник Военной Полиции обязан уведомить руководство соответствующей армии либо Куратора Военной Полиции и действовать в рамках служебной необходимости.", category: "устав ВП" },
    { id: 737, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.1.3", text: "Офицеры Военной Полиции имеют право проверять ВЧ на наявность чрезвычайных ситуаций.", category: "устав ВП" },
    { id: 738, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.1.4", text: "Сотрудники Военной Полиции могут выполнять специальные поручения от Куратора Военной Полиции находясь без рабочей формы (Вести развед/проверяющую деятельность). Дополнение к пункту 3.1.4: 1. Сотрудникам Военной Полиции запрещается оформление надзоров в то время когда они находятся без рабочей формы. 2. Сотрудникам Военной Полиции при выполнении специальных поручений от Куратора Военной Полиции запрещается превышать свои полномочия. 3. Сотрудникам Военной Полиции при выполнении специальных поручений находясь без рабочей формы запрещается оформлять надзоры. Все собранные материалы передаются руководству той структуры где было выявлено нарушение.", category: "устав ВП" },
    { id: 739, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.2", text: "Сотрудники военной полиции имеют право получить любую информацию на сотрудников министерства обороны.", category: "устав ВП" },
    { id: 740, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.4", text: "Сотрудники военной полиции имеют право на личную жизнь вне рабочего времени.", category: "устав ВП" },
    { id: 741, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.5", text: "Сотрудники военной полиции имеют право на отпуск в соответствии с современным Трудовым Кодексом.", category: "устав ВП" },
    { id: 742, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.5.1", text: "Отпуск может быть взят только один раз в месяц.", category: "устав ВП" },
    { id: 743, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.5.2", text: "Офицер военной полиции имеет право на отпуск в течении семи календарных дней.", category: "устав ВП" },
    { id: 744, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.6", text: "Офицер военной полиции имеет полное право иметь надетую балаклаву на своём лице во время проверки людных мест в рамках выполнения своих служебных обязанностей.", category: "устав ВП" },
    { id: 745, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.6.1", text: "Нахождение сотрудника Военной Полиции в людных местах без служебной необходимости влечёт дисциплинарную ответственность вплоть до увольнения. (Примечание: Данный пункт распространяется и на Куратора Военной Полиции).", category: "устав ВП" },
    { id: 746, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.6.2", text: "Офицер военной полиции обязан снять маску при приказе руководства армии на территории военной базы.", category: "устав ВП" },
    { id: 747, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.7", text: "Сотрудник военной полиции имеет право покинуть военную часть при надетой балаклаве.", category: "устав ВП" },
    { id: 748, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.8", text: "Если человек с опознавательными знакам военнослужащего (военная форма, жетон, нашивки, погоны) находится возле военной базы, охраняемого объекту, полицейского участку, офиса ФБР, здания правительства, мест скопления большего количества людей (ЗЗ) находится в маске к данному лицу может быть проведена процедура установки личности.", category: "устав ВП" },
    { id: 749, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.8.1", text: "Сначала сотрудник обязан потребовать снять маску, перед этим идентифицировать себя как сотрудника военной полиции.", category: "устав ВП" },
    { id: 750, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.8.2", text: "В случае отказа гражданина сотрудник Военной Полиции имеет право применить соразмерную физическую силу для установления личности.", category: "устав ВП" },
    { id: 751, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.8.3", text: "В случае отказа гражданина покинуть транспортное средство офицер Военной Полиции имеет право принудительно извлечь его.", category: "устав ВП" },
    { id: 752, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.9", text: "Сотрудники Военной Полиции имеют доступ к базе данных всех сотрудников МО.", category: "устав ВП" },
    { id: 753, law: "Устав Военной Полиции", chapter: "Глава 3. Полномочия и права сотрудников", point: "3.10", text: "Каждый офицер Военной Полиции имеет право выполнять поставленные задачи на личном транспорте, предварительно зарегистрировав и поставив его на учет в реестре автотранспорта Министерства Обороны.", category: "устав ВП" },
    { id: 754, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.1", text: "Нарушать Конституцию, Федеральное Постановление, Устав Военной полиции, Уголовный, Административный и Трудовой Кодексы.", category: "устав ВП" },
    { id: 755, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.2", text: "Бездействовать при угрозе органам высшей исполнительной власти.", category: "устав ВП" },
    { id: 756, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.3", text: "Прогуливать рабочий день.", category: "устав ВП" },
    { id: 757, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.3.1", text: "Рабочий день с Понедельника по Субботу с 11:00 до 20:00.", category: "устав ВП" },
    { id: 758, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.3.2", text: "В Воскресенье выходной день.", category: "устав ВП" },
    { id: 759, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.3.3", text: "Обеденный перерыв с 15:00 до 16:00 ежедневно.", category: "устав ВП" },
    { id: 760, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.4", text: "Пользоваться имуществом организации в личных целях.", category: "устав ВП" },
    { id: 761, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.5", text: "Выпивать спиртные напитки находясь в рабочее время в форме.", category: "устав ВП" },
    { id: 762, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.5.2", text: "Запрещено иметь в позывном собственное имя/фамилию, имена других сотрудников МО.", category: "устав ВП" },
    { id: 763, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.5.3", text: "Позывной не должен содержать нецензурной брани/оскорбительный слов/фашистских или нацистских лозунгов/цифр/символов/иностранных букв/пробелов и должен состоять только из одного слова на русском языке.", category: "устав ВП" },
    { id: 764, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.7", text: "Употреблять и хранить укроптические и психотропные вещества.", category: "устав ВП" },
    { id: 765, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.8", text: "Употребление нецензурной брани.", category: "устав ВП" },
    { id: 766, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.9", text: "Оспаривать законные указания руководства, в лице Куратора ВП, Руководства армии.", category: "устав ВП" },
    { id: 767, law: "Устав Военной Полиции", chapter: "Глава 4. Сотрудникам запрещается", point: "4.10", text: "Нарушать дресс-код министерства обороны.", category: "устав ВП" },
    { id: 768, law: "Устав Военной Полиции", chapter: "Глава 5. Особые положения при проведении тренировок и лекционных задач", point: "5.1", text: "Сотрудник военной полиции имеет право помогать руководству министерства обороны, относящимся к проведению тренировок и лекций.", category: "устав ВП" },
    { id: 769, law: "Устав Военной Полиции", chapter: "Глава 5. Особые положения при проведении тренировок и лекционных задач", point: "5.2", text: "Куратор военной полиции, с разрешения руководящего состава, имеет право дать боевую задачу любому бойцу Военно-Морского Флота, Сухопутных Войск, Сотруднику Тюрьмы Строгого Режима.", category: "устав ВП" },
    { id: 770, law: "Устав Военной Полиции", chapter: "Глава 5. Особые положения при проведении тренировок и лекционных задач", point: "5.3", text: "Офицер Военной полиции может попросить помощи у сотрудника Delta в поиске дезертиров и уклонистов.", category: "устав ВП" },
    { id: 771, law: "Устав Военной Полиции", chapter: "Глава 5. Особые положения при проведении тренировок и лекционных задач", point: "5.4", text: "Офицер Военной полиции с разрешением рук-во армии, может проводить тренировки, лекции, мероприятия с составом армии.", category: "устав ВП" },
    { id: 772, law: "Устав Военной Полиции", chapter: "Глава 5. Особые положения при проведении тренировок и лекционных задач", point: "5.4.1", text: "Куратор ВП с предупреждением рук-во армии, может проводить тренировки, лекции, мероприятия с составом армии.", category: "устав ВП" },
    { id: 773, law: "Устав Военной Полиции", chapter: "Глава 6. Пользование рацией", point: "6.1", text: "Рацией разрешено пользоваться строго в служебных целях.", category: "устав ВП" },
    { id: 774, law: "Устав Военной Полиции", chapter: "Глава 6. Пользование рацией", point: "6.2", text: "При пользовании рации департамента, офицер военной полиции обязан использовать код военной полиции. (ВП).", category: "устав ВП" },
    { id: 775, law: "Устав Военной Полиции", chapter: "Глава 6. Пользование рацией", point: "6.4", text: "Офицер военной полиции имеет полный доступ к закрытым каналам Министерства Обороны.", category: "устав ВП" },
    { id: 776, law: "Устав Военной Полиции", chapter: "Глава 6. Пользование рацией", point: "6.5", text: "Запрещено использовать рацию для покупки, продажи и рекламы имущества, а также нарушать правила использования рации.", category: "устав ВП" },
    { id: 777, law: "Устав Военной Полиции", chapter: "Глава 7. Транспорт военной полиции", point: "7.1", text: "Запрещено использовать транспорт Министерства обороны в личных целях.", category: "устав ВП" },
    { id: 778, law: "Устав Военной Полиции", chapter: "Глава 7. Транспорт военной полиции", point: "7.2", text: "Запрещено целенаправленно портить имущество государственных организаций.", category: "устав ВП" },
    { id: 779, law: "Устав Военной Полиции", chapter: "Глава 7. Транспорт военной полиции", point: "7.3", text: "Офицеру Военной Полиции разрешено использовать личный т/с в рабочих целях.", category: "устав ВП" },
    { id: 780, law: "Устав Военной Полиции", chapter: "Глава 8. Особые положения при проведении проверяющей деятельности", point: "8.1", text: "Проверку МО назначает Куратор ВП или его заместители при уведомлении лидера / заместителя организации.", category: "устав ВП" },
    { id: 781, law: "Устав Военной Полиции", chapter: "Глава 8. Особые положения при проведении проверяющей деятельности", point: "8.1.1", text: "Проверка может быть плановой так и внеплановой. Проверки назначаются не менее чем за 20 минут до проведения самой проверки. Внеплановую проверку нельзя назначать в период проведения мероприятия \"Битва за завод\".", category: "устав ВП" },
    { id: 782, law: "Устав Военной Полиции", chapter: "Глава 8. Особые положения при проведении проверяющей деятельности", point: "8.2", text: "Проверки от ВП проводятся строго по регламенту проведения проверок.", category: "устав ВП" },
    { id: 783, law: "Устав Военной Полиции", chapter: "Глава 8. Особые положения при проведении проверяющей деятельности", point: "8.3", text: "Сотрудники ВП могут проводить проверки военнослужащих ЛСа/СФа и сотрудников ТСР, на наличие запрещенных предметов, отсутствия необходимых лицензий, а также наличие в крови запрещенных веществ.", category: "устав ВП" },
    { id: 784, law: "Устав Военной Полиции", chapter: "Глава 8. Особые положения при проведении проверяющей деятельности", point: "8.3.1", text: "При проверке военнослужащих/сотрудников на наличие в крови запрещенных веществ Куратор ВП/Заместитель Куратора ВП обязан вызвать сотрудника Медицинского Центра для проведения анализа путем забора венозной крови.", category: "устав ВП" },
    { id: 785, law: "Устав Военной Полиции", chapter: "Глава 8. Особые положения при проведении проверяющей деятельности", point: "8.3.2", text: "Проведение проверок личного состава Министерства Обороны, включая военнослужащих ЛСа, СФа и сотрудников ТСР, является обязательным. Все организации Министерства Обороны обязаны проходить проверки, назначенные Куратором Военной Полиции или его заместителями, в установленном порядке и в назначенное время.", category: "устав ВП" },
    { id: 786, law: "Устав Военной Полиции", chapter: "Глава 8. Особые положения при проведении проверяющей деятельности", point: "8.3.3", text: "Руководство проверяемой организации обязано обеспечить явку личного состава для прохождения проверки и оказать необходимое содействие сотрудникам Военной Полиции. Необоснованный отказ от прохождения проверки, препятствование её проведению или уклонение от проверки со стороны руководства либо сотрудников организации является основанием для применения дисциплинарных мер в соответствии с действующими нормативными актами.", category: "устав ВП" },
    { id: 787, law: "Устав Военной Полиции", chapter: "Глава 8. Особые положения при проведении проверяющей деятельности", point: "8.4", text: "Офицер военной полиции обязан зафиксировать нахождение запрещенных предметов или же отсутствия необходимых лицензий, для предоставления необходимых предметов.", category: "устав ВП" },
    { id: 788, law: "Устав Военной Полиции", chapter: "Глава 8. Особые положения при проведении проверяющей деятельности", point: "8.5", text: "Во время проверки проходит оценка по 5-ти бальной шкале.", category: "устав ВП" },
    { id: 789, law: "Устав Военной Полиции", chapter: "Глава 8. Особые положения при проведении проверяющей деятельности", point: "8.6", text: "Если организация проходит проверку на 2/5 баллов или меньше, то в течении недели, она обязательно проходит внеплановые проверки для улучшения результата. Исключение: в регламентированный выходной день(воскресенье), проверку проводить нельзя.", category: "устав ВП" },
    { id: 790, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.1", text: "В Военной полиции вводится система аттестации сотрудников с целью оценки уровня профессиональной подготовки, дисциплины и соответствия занимаемой должности.", category: "устав ВП" },
    { id: 791, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.2", text: "Ответственными за проведение аттестации являются Кураторы и Заместители Куратора Военной полиции.", category: "устав ВП" },
    { id: 792, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.3", text: "Аттестация проводится ежемесячно в форме тестирования, состоящего из 15 вопросов.", category: "устав ВП" },
    { id: 793, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.4", text: "Для успешного прохождения аттестации сотрудник должен набрать не менее 12 правильных ответов из 15 (проходной балл — 12/15).", category: "устав ВП" },
    { id: 794, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.5", text: "Результаты аттестации фиксируются в аттестационном журнале и утверждаются Куратором или старшим офицером Военной полиции.", category: "устав ВП" },
    { id: 795, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.6", text: "При двухразовом провале аттестации сотрудник основного состава ВП подлежит понижению. В случае стажёра его стажировка прекращается.", category: "устав ВП" },
    { id: 796, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.7", text: "Ответы на тестовые вопросы аттестации содержатся в Уставе Военной полиции и Уставе ТСР.", category: "устав ВП" },
    { id: 797, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.8", text: "В случае попытки распространения, передачи или публикации вопросов аттестационного теста, а также фактического разглашения их содержания, сотрудник подлежит дисциплинарному взысканию в виде внесения в “Чёрный список Министерства Обороны” (ЧС МО) Второй степени.", category: "устав ВП" },
    { id: 798, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.9", text: "В случае многочисленных дисциплинарных нарушений или неудовлетворительных результатов служебной деятельности, Куратор или Заместитель Куратора Военной полиции вправе назначить переаттестацию сотрудника.", category: "устав ВП" },
    { id: 799, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.10", text: "Переаттестация должна быть пройдена в срок не позднее 7 календарных дней с момента получения уведомления о её назначении.", category: "устав ВП" },
    { id: 800, law: "Устав Военной Полиции", chapter: "Глава 9. Аттестация военной полиции", point: "9.11", text: "Непрохождение переаттестации в установленный срок влечёт применение дисциплинарных мер, предусмотренных Уставом Военной полиции.", category: "устав ВП" },
    { id: 801, law: "Устав Военной Полиции", chapter: "Глава 10. Подчинение руководства армий", point: "10.1", text: "Руководство армий подчиняется Заместителям Куратора Военной Полиции и вышестоящему руководству Военной Полиции в рамках их служебных полномочий.", category: "устав ВП" },
    { id: 802, law: "Устав Военной Полиции", chapter: "Глава 10. Подчинение руководства армий", point: "10.2", text: "Законные требования Заместителей Куратора и руководства Военной Полиции обязательны для исполнения руководством армий.", category: "устав ВП" },
    { id: 803, law: "Устав Военной Полиции", chapter: "Глава 10. Подчинение руководства армий", point: "10.3", text: "Руководство армий не вправе без веской причины отказывать в выполнении законных требований руководства Военной Полиции.", category: "устав ВП" }
];

window.articlesDB = articlesDB;    
